def _load_soperator_upgrade_checkpoint(path: Path) -> dict[str, Any] | None:
    if not path.exists():
        return None
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        raise RuntimeError(f"Could not parse Soperator upgrade checkpoint {path}.") from exc
    if not isinstance(payload, dict):
        raise RuntimeError(f"Soperator upgrade checkpoint {path} must contain a JSON object.")
    if payload.get("schema") != SOPERATOR_UPGRADE_CHECKPOINT_SCHEMA:
        raise RuntimeError(f"Unsupported Soperator upgrade checkpoint schema in {path}.")
    return payload


def _soperator_upgrade_phase_state(
    checkpoint: dict[str, Any],
    phase_id: str,
) -> dict[str, Any]:
    raw_state = checkpoint.setdefault("phase_state", {})
    if not isinstance(raw_state, dict):
        raw_state = {}
        checkpoint["phase_state"] = raw_state
    phase = raw_state.setdefault(phase_id, {})
    if not isinstance(phase, dict):
        raise RuntimeError(
            f"Soperator upgrade checkpoint phase_state.{phase_id} must be a mapping."
        )
    return phase


def _soperator_upgrade_completed_phase_set(checkpoint: Mapping[str, Any]) -> set[str]:
    return {
        str(phase or "").strip()
        for phase in checkpoint.get("completed_phases", []) or []
        if str(phase or "").strip()
    }


def _ordered_soperator_upgrade_completed_phases(phases: Iterable[str]) -> list[str]:
    completed = {str(phase or "").strip() for phase in phases if str(phase or "").strip()}
    ordered = [phase for phase in _SOPERATOR_UPGRADE_PLANNED_PHASE_IDS if phase in completed]
    ordered.extend(sorted(completed - set(_SOPERATOR_UPGRADE_PLANNED_PHASE_IDS)))
    return ordered


def _soperator_upgrade_checkpoint_complete(checkpoint: Mapping[str, Any]) -> bool:
    if str(checkpoint.get("pending_phase", "") or "").strip() != "none":
        return False
    completed = _soperator_upgrade_completed_phase_set(checkpoint)
    return bool(completed) and set(_SOPERATOR_UPGRADE_PLANNED_PHASE_IDS) <= completed


def _soperator_upgrade_phase_fast_verification(
    checkpoint: Mapping[str, Any],
    phase_id: str,
) -> Mapping[str, Any]:
    phase_state = checkpoint.get("phase_state")
    phase_state_map = phase_state if isinstance(phase_state, Mapping) else {}
    phase = phase_state_map.get(phase_id)
    phase_map = phase if isinstance(phase, Mapping) else {}
    verification = phase_map.get("fast_verification")
    if isinstance(verification, Mapping):
        return verification
    stage_state = checkpoint.get("stage_verification")
    stage_state_map = stage_state if isinstance(stage_state, Mapping) else {}
    stage = stage_state_map.get(phase_id)
    stage_map = stage if isinstance(stage, Mapping) else {}
    verification = stage_map.get("fast_verification")
    return verification if isinstance(verification, Mapping) else {}


def _soperator_upgrade_checkpoint_artifact_path(project_dir: Path, value: object) -> Path | None:
    text = _non_empty_text(value)
    if not text:
        return None
    path = Path(text).expanduser()
    return path if path.is_absolute() else project_dir / path


def _soperator_upgrade_completed_phase_reverify_issue(
    checkpoint: Mapping[str, Any],
    phase_id: str,
    *,
    project_dir: Path,
) -> str:
    verification = _soperator_upgrade_phase_fast_verification(checkpoint, phase_id)
    status = str(verification.get("status", "") or "").strip().lower().replace("_", "-")
    if status not in {"passed", "skipped"}:
        return "missing or failed fast verification"
    if status == "skipped":
        return ""
    if phase_id == "discovery":
        discovery = checkpoint.get("discovery")
        discovery_map = discovery if isinstance(discovery, Mapping) else {}
        manifest_path = _soperator_upgrade_checkpoint_artifact_path(
            project_dir,
            discovery_map.get("path"),
        )
        bundle_dir = _soperator_upgrade_checkpoint_artifact_path(
            project_dir,
            discovery_map.get("bundle_dir"),
        )
        if manifest_path is None or not manifest_path.exists():
            return "discovery manifest is missing"
        if bundle_dir is None or not bundle_dir.exists():
            return "discovery bundle directory is missing"
    elif phase_id == "backup":
        backup = checkpoint.get("backup")
        backup_map = backup if isinstance(backup, Mapping) else {}
        archive_path = _soperator_upgrade_checkpoint_artifact_path(
            project_dir,
            backup_map.get("path"),
        )
        if archive_path is None or not archive_path.exists():
            return "backup archive is missing"
        if not _non_empty_text(backup_map.get("sha256")):
            return "backup archive hash is missing"
        if not _non_empty_text(backup_map.get("manifest_sha256")):
            return "backup manifest hash is missing"
    elif phase_id == "protected-state-capture":
        safety = checkpoint.get("upgrade_safety")
        safety_map = safety if isinstance(safety, Mapping) else {}
        protected = safety_map.get("protected_customer_state")
        protected_map = protected if isinstance(protected, Mapping) else {}
        if not _non_empty_text(protected_map.get("before_hash")):
            return "protected-state baseline hash is missing"
    return ""


def _soperator_upgrade_verified_completed_phase_set(
    checkpoint: dict[str, Any],
    *,
    project_dir: Path,
) -> set[str]:
    completed = _soperator_upgrade_completed_phase_set(checkpoint)
    demoted: dict[str, str] = {}
    for phase_id in _SOPERATOR_UPGRADE_PLANNED_PHASE_IDS:
        if phase_id not in completed:
            continue
        issue = _soperator_upgrade_completed_phase_reverify_issue(
            checkpoint,
            phase_id,
            project_dir=project_dir,
        )
        if not issue:
            continue
        completed.discard(phase_id)
        demoted[phase_id] = issue
    if demoted:
        checkpoint["completed_phases"] = _ordered_soperator_upgrade_completed_phases(completed)
        _append_soperator_upgrade_event(
            checkpoint,
            "completed-phase-reverify-required",
            phase=", ".join(demoted),
            reason="; ".join(f"{phase}: {reason}" for phase, reason in demoted.items()),
        )
    return completed


def _soperator_upgrade_config_fingerprint_from_payload(
    payload: Mapping[str, Any],
    *,
    checkpoint_path: Path,
    label: str,
) -> _SoperatorUpgradeConfigFingerprint:
    missing = [
        key
        for key in (
            "values_sha256",
            "slurm_policy_sha256",
            "accounting_policy_sha256",
            "node_mapping_sha256",
        )
        if not _non_empty_text(payload.get(key))
    ]
    if missing:
        raise RuntimeError(
            f"Soperator upgrade checkpoint {checkpoint_path} is missing {label} "
            "protected config fingerprint field(s): "
            + ", ".join(missing)
            + ". Rerun cannot safely resume this phase."
        )
    return _SoperatorUpgradeConfigFingerprint(
        values_sha256=str(payload["values_sha256"]),
        slurm_policy_sha256=str(payload["slurm_policy_sha256"]),
        accounting_policy_sha256=str(payload["accounting_policy_sha256"]),
        node_mapping_sha256=str(payload["node_mapping_sha256"]),
    )


def _soperator_upgrade_checkpoint_events(checkpoint: Mapping[str, Any]) -> tuple[str, ...]:
    events = checkpoint.get("events")
    if not isinstance(events, list):
        return ()
    names: list[str] = []
    for item in events:
        if not isinstance(item, Mapping):
            continue
        event = _non_empty_text(item.get("event"))
        if event:
            names.append(event)
    return tuple(names)


def _soperator_upgrade_checkpoint_has_pending_activechecks_restore(
    checkpoint: Mapping[str, Any],
) -> bool:
    activechecks = checkpoint.get("activechecks")
    activechecks_map = activechecks if isinstance(activechecks, Mapping) else {}
    if not bool(activechecks_map.get("required")):
        return False
    events = _soperator_upgrade_checkpoint_events(checkpoint)
    if not any(event.startswith("activechecks-suspend") for event in events):
        return False
    if "activechecks-restored" in events or "activechecks-restored-after-failure" in events:
        return False
    failure = checkpoint.get("failure")
    return not (isinstance(failure, Mapping) and failure.get("activechecks_restore") == "restored")


def _soperator_upgrade_checkpoint_lifecycle(
    checkpoint: Mapping[str, Any],
    *,
    checkpoint_path: Path,
) -> _SoperatorActiveChecksLifecycle:
    activechecks = checkpoint.get("activechecks")
    activechecks_map = activechecks if isinstance(activechecks, Mapping) else {}
    snapshots = activechecks_map.get("snapshots")
    if not isinstance(snapshots, list):
        raise RuntimeError(
            f"Soperator upgrade checkpoint {checkpoint_path} is missing ActiveChecks snapshots; "
            "rerun cannot safely restore the pre-upgrade values."
        )
    parsed: list[_SoperatorUpgradeValueSnapshot] = []
    seen_paths: set[str] = set()
    for item in snapshots:
        if not isinstance(item, Mapping):
            continue
        path = _non_empty_text(item.get("path"))
        if path not in _SOPERATOR_ACTIVECHECKS_UPGRADE_PATHS:
            continue
        seen_paths.add(path)
        parsed.append(
            _SoperatorUpgradeValueSnapshot(
                path=path,
                present=bool(item.get("present")),
                value=copy.deepcopy(item.get("value")),
            )
        )
    missing = [path for path in _SOPERATOR_ACTIVECHECKS_UPGRADE_PATHS if path not in seen_paths]
    if missing:
        raise RuntimeError(
            f"Soperator upgrade checkpoint {checkpoint_path} is missing ActiveChecks snapshots "
            f"for: {', '.join(missing)}. Rerun cannot safely restore the pre-upgrade values."
        )
    required = bool(activechecks_map.get("required")) or any(
        snapshot.value is True for snapshot in parsed
    )
    return _SoperatorActiveChecksLifecycle(required=required, snapshots=tuple(parsed))


def _soperator_upgrade_resume_checkpoint(
    *,
    checkpoint_path: Path,
    plan: _HelmChartUpgradePlan,
    paths: ProjectPaths,
) -> tuple[dict[str, Any] | None, _SoperatorActiveChecksLifecycle | None]:
    checkpoint = _load_soperator_upgrade_checkpoint(checkpoint_path)
    if checkpoint is None:
        return None, None
    checkpoint_target_ref = _non_empty_text(checkpoint.get("target_ref"))
    if checkpoint_target_ref and checkpoint_target_ref != plan.target.target_ref:
        raise RuntimeError(
            f"Soperator upgrade checkpoint {checkpoint_path} belongs to target "
            f"{checkpoint_target_ref!r}, not {plan.target.target_ref!r}."
        )
    checkpoint_target_version = _non_empty_text(checkpoint.get("target_version"))
    if checkpoint_target_version and checkpoint_target_version != plan.target_version:
        raise RuntimeError(
            f"Unfinished Soperator upgrade checkpoint {checkpoint_path} targets chart version "
            f"{checkpoint_target_version}, but this run requested {plan.target_version}. "
            "Rerun the same upgrade command first so cxcli can restore the checkpointed "
            "ActiveChecks values."
        )
    has_phase_contract = isinstance(checkpoint.get("planned_phases"), list)
    completed = _soperator_upgrade_completed_phase_set(checkpoint)
    pending_phase = str(checkpoint.get("pending_phase", "") or "").strip()
    legacy_activechecks_restore = _soperator_upgrade_checkpoint_has_pending_activechecks_restore(
        checkpoint
    )
    if not has_phase_contract:
        if not legacy_activechecks_restore:
            raise RuntimeError(
                f"Soperator upgrade checkpoint {checkpoint_path} was created before "
                "phase-bounded resume metadata was available. cxcli cannot prove where "
                "to resume safely. Review the checkpoint and recovery instructions before "
                "removing it."
            )
        checkpoint["planned_phases"] = list(_SOPERATOR_UPGRADE_PLANNED_PHASE_IDS)
        restore_index = _SOPERATOR_UPGRADE_PLANNED_PHASE_IDS.index("activechecks-restore")
        checkpoint["completed_phases"] = list(_SOPERATOR_UPGRADE_PLANNED_PHASE_IDS[:restore_index])
        checkpoint["pending_phase"] = "activechecks-restore"
        checkpoint["pending_reason"] = "legacy checkpoint requires ActiveChecks restore"
        checkpoint.setdefault("phase_state", {})
    elif pending_phase and pending_phase != "none":
        if pending_phase not in _SOPERATOR_UPGRADE_PLANNED_PHASE_IDS:
            raise RuntimeError(
                f"Soperator upgrade checkpoint {checkpoint_path} has unsupported pending "
                f"phase {pending_phase!r}. Review or remove the checkpoint before executing."
            )
    elif has_phase_contract and not _soperator_upgrade_checkpoint_complete(checkpoint):
        # Incomplete phase-aware checkpoints with pending_phase=none are treated as
        # resumable from the first uncompleted phase.
        checkpoint["completed_phases"] = _ordered_soperator_upgrade_completed_phases(completed)
        checkpoint["pending_phase"] = "none"
        checkpoint.setdefault("pending_reason", "")
    elif not _soperator_upgrade_checkpoint_complete(checkpoint):
        raise RuntimeError(
            f"Soperator upgrade checkpoint {checkpoint_path} does not contain completed "
            "phase metadata. Review or remove the checkpoint before executing."
        )
    lifecycle = _soperator_upgrade_checkpoint_lifecycle(
        checkpoint,
        checkpoint_path=checkpoint_path,
    )
    checkpoint["target_ref"] = plan.target.target_ref
    checkpoint["selector"] = plan.target.selector
    checkpoint["namespace"] = plan.namespace or "default"
    checkpoint["release_name"] = plan.release_name
    checkpoint["current_version"] = plan.current_version
    checkpoint["target_version"] = plan.target_version
    checkpoint["checkpoint_path"] = _soperator_upgrade_relative_path(
        checkpoint_path,
        root=paths.project_dir,
    )
    checkpoint["reports"] = {
        "upgrade": _soperator_upgrade_relative_path(
            paths.reports_dir / SOPERATOR_UPGRADE_REPORT_FILENAME,
            root=paths.project_dir,
        ),
        "upgrade_json": _soperator_upgrade_relative_path(
            paths.reports_dir / SOPERATOR_UPGRADE_REPORT_JSON_FILENAME,
            root=paths.project_dir,
        ),
    }
    _append_soperator_upgrade_event(
        checkpoint,
        "resumed",
        reason=(
            "pending-activechecks-restore"
            if legacy_activechecks_restore and not has_phase_contract
            else "phase-bounded-resume"
        ),
        pending_phase=str(checkpoint.get("pending_phase") or "none"),
    )
    return checkpoint, lifecycle


def _append_soperator_upgrade_event(
    checkpoint: dict[str, Any],
    event: str,
    **details: Any,
) -> None:
    events = checkpoint.setdefault("events", [])
    if not isinstance(events, list):
        events = []
        checkpoint["events"] = events
    entry: dict[str, Any] = {"time": _soperator_upgrade_now_iso(), "event": event}
    entry.update({key: value for key, value in details.items() if value is not None})
    events.append(entry)
    checkpoint["status"] = event


def _soperator_upgrade_stage_verification_state(checkpoint: dict[str, Any]) -> dict[str, Any]:
    state = checkpoint.setdefault("stage_verification", {})
    if not isinstance(state, dict):
        state = {}
        checkpoint["stage_verification"] = state
    return state


def _soperator_upgrade_stage_verification_reports(
    checkpoint: Mapping[str, Any],
) -> list[dict[str, Any]]:
    state = checkpoint.get("stage_verification")
    state_map = state if isinstance(state, Mapping) else {}
    phase_history = checkpoint.get("phase_history")
    phase_by_id: dict[str, Mapping[str, Any]] = {}
    if isinstance(phase_history, list):
        for item in phase_history:
            if not isinstance(item, Mapping):
                continue
            phase_id = _non_empty_text(item.get("id"))
            if phase_id:
                phase_by_id[phase_id] = item
    reports: list[dict[str, Any]] = []
    for phase_id in _SOPERATOR_FAST_STAGE_VERIFICATION_PHASE_IDS:
        phase = state_map.get(phase_id)
        if not isinstance(phase, Mapping):
            phase = phase_by_id.get(phase_id, {})
        reports.append(stage_fast_verification_report(phase_id, phase))
    return reports


def _record_soperator_upgrade_stage_fast_verification(
    *,
    checkpoint: dict[str, Any],
    phase_id: str,
    summary: str,
    checks: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    status = stage_fast_verification_status(checks)
    payload = build_stage_fast_verification_payload(
        phase_id=phase_id,
        status=status,
        summary=summary,
        checks=checks,
    )
    state = _soperator_upgrade_stage_verification_state(checkpoint)
    state[phase_id] = {"fast_verification": payload}
    phase = _soperator_upgrade_phase_state(checkpoint, phase_id)
    phase["fast_verification"] = payload
    current_phase = checkpoint.get("current_phase")
    if isinstance(current_phase, dict) and current_phase.get("id") == phase_id:
        current_phase["fast_verification"] = payload
    phase_history = checkpoint.get("phase_history")
    if isinstance(phase_history, list):
        for item in reversed(phase_history):
            if isinstance(item, dict) and item.get("id") == phase_id:
                item["fast_verification"] = payload
                break
    event_status = (
        "failed" if status == "failed" else "skipped" if status == "skipped" else "passed"
    )
    _append_soperator_upgrade_event(
        checkpoint,
        "stage-fast-verification-" + event_status,
        phase=phase_id,
        status=status,
        summary=summary,
    )
    return payload


def _write_soperator_upgrade_checkpoint(path: Path, checkpoint: Mapping[str, Any]) -> None:
    _write_text_atomic(path, json.dumps(checkpoint, indent=2, sort_keys=True) + "\n")


def _write_soperator_upgrade_report(
    paths: ProjectPaths,
    checkpoint: Mapping[str, Any],
) -> tuple[Path, Path]:
    paths.reports_dir.mkdir(parents=True, exist_ok=True)
    json_path = paths.reports_dir / SOPERATOR_UPGRADE_REPORT_JSON_FILENAME
    markdown_path = paths.reports_dir / SOPERATOR_UPGRADE_REPORT_FILENAME
    safety = checkpoint.get("upgrade_safety")
    safety_map = safety if isinstance(safety, Mapping) else {}
    stage_verification_reports = _soperator_upgrade_stage_verification_reports(checkpoint)
    json_payload = dict(checkpoint)
    json_payload["stage_verification"] = stage_verification_reports
    for key in (
        "protected_customer_state",
        "remediation_approvals",
        "post_upgrade_verification",
        "fast_smoke",
        "heavy_validation_followups",
        "backup",
        "zero_downtime_eligibility",
    ):
        if key in safety_map:
            json_payload[key] = safety_map[key]
    _write_text_atomic(json_path, json.dumps(json_payload, indent=2, sort_keys=True) + "\n")

    activechecks = checkpoint.get("activechecks")
    activechecks_map = activechecks if isinstance(activechecks, Mapping) else {}
    snapshots = activechecks_map.get("snapshots")
    snapshot_lines: list[str] = []
    if isinstance(snapshots, list):
        for item in snapshots:
            if not isinstance(item, Mapping):
                continue
            path = str(item.get("path") or "")
            if not path:
                continue
            value = item.get("value") if bool(item.get("present")) else "absent"
            snapshot_lines.append(f"- `{path}` original value: `{value}`")
    if not snapshot_lines:
        snapshot_lines.append("- No ActiveChecks value changes were required.")

    events = checkpoint.get("events")
    event_lines: list[str] = []
    if isinstance(events, list):
        for index, item in enumerate(events, start=1):
            if not isinstance(item, Mapping):
                continue
            event = str(item.get("event") or "event")
            when = str(item.get("time") or "")
            detail_parts: list[str] = []
            for detail_key in ("phase", "reason", "status", "passed", "error"):
                if detail_key not in item:
                    continue
                detail_value = item.get(detail_key)
                if isinstance(detail_value, (str, int, float, bool)):
                    detail_parts.append(f"{detail_key}={detail_value}")
            report_refs = item.get("validation_reports")
            report_text = ""
            if isinstance(report_refs, list):
                report_names = [str(report) for report in report_refs if str(report or "").strip()]
                if report_names:
                    report_text = (
                        " (validation reports: "
                        + ", ".join(f"`{report}`" for report in report_names)
                        + ")"
                    )
            detail_text = " (" + ", ".join(detail_parts) + ")" if detail_parts else ""
            event_lines.append(
                f"{index}. `{event}`"
                + (f" at `{when}`" if when else "")
                + detail_text
                + report_text
            )
    if not event_lines:
        event_lines.append("1. `planned`")

    current_phase = checkpoint.get("current_phase")
    current_phase_map = current_phase if isinstance(current_phase, Mapping) else {}
    current_phase_id = str(current_phase_map.get("id") or "unknown")
    current_phase_comment = str(current_phase_map.get("comment") or "No phase comment recorded.")
    current_phase_component = str(current_phase_map.get("component") or "").strip()
    current_phase_component_text = (
        f" for `{current_phase_component}`" if current_phase_component else ""
    )
    current_phase_top_level_stage = str(
        current_phase_map.get("top_level_stage")
        or _soperator_upgrade_top_level_stage(current_phase_id)
    )
    current_phase_stage_text = f" (top-level stage: `{current_phase_top_level_stage}`)"
    phase_history = checkpoint.get("phase_history")
    phase_history_lines: list[str] = []
    if isinstance(phase_history, list):
        for item in phase_history:
            if not isinstance(item, Mapping):
                continue
            phase_id = str(item.get("id") or "").strip()
            if not phase_id:
                continue
            comment = str(item.get("comment") or "No phase comment recorded.")
            component = str(item.get("component") or "").strip()
            component_text = f" for `{component}`" if component else ""
            top_level_stage = str(
                item.get("top_level_stage") or _soperator_upgrade_top_level_stage(phase_id)
            )
            stage_text = f" (top-level stage: `{top_level_stage}`)"
            updated_at = str(item.get("updated_at") or "")
            timestamp = f" at `{updated_at}`" if updated_at else ""
            phase_history_lines.append(
                f"- `{phase_id}`{stage_text}{component_text}{timestamp}: {comment}"
            )
    if not phase_history_lines:
        phase_history_lines.append("- No phase history recorded.")

    backup = checkpoint.get("backup")
    backup_map = backup if isinstance(backup, Mapping) else {}
    backup_lines = [
        f"- Archive: `{backup_map.get('path') or 'not-created'}`",
        f"- Size: `{backup_map.get('size_bytes') or 0}` bytes",
        f"- SHA256: `{backup_map.get('sha256') or 'not-created'}`",
        f"- Manifest SHA256: `{backup_map.get('manifest_sha256') or 'not-created'}`",
        "- Sensitive material: raw Kubernetes Secrets are included; accounting DB dump "
        "is included only when live chart-managed accounting is present.",
        "- Report redaction: Secret values and SQL dump contents, when present, are not printed.",
    ]
    categories = backup_map.get("included_categories")
    if isinstance(categories, list) and categories:
        backup_lines.append(
            "- Included categories: " + ", ".join(f"`{item}`" for item in categories)
        )

    discovery = checkpoint.get("discovery")
    discovery_map = discovery if isinstance(discovery, Mapping) else {}
    discovery_lines = [
        f"- Bundle: `{discovery_map.get('bundle_dir') or 'not-created'}`",
        f"- Manifest: `{discovery_map.get('path') or 'not-created'}`",
        f"- Redaction: `{discovery_map.get('redaction') or 'support'}`",
        "- Scope: read-only Soperator discovery; raw restore material and DB dumps are not included.",
    ]

    mk8s = checkpoint.get("mk8s")
    mk8s_map = mk8s if isinstance(mk8s, Mapping) else {}
    mk8s_lines = [
        f"- Requested: `{bool(mk8s_map.get('requested'))}`",
        f"- Kubernetes target: `{mk8s_map.get('target_k8s_version') or 'unchanged'}`",
        f"- OS target: `{mk8s_map.get('target_os') or 'unchanged'}`",
        f"- GPU stack target: `{mk8s_map.get('target_gpu_stack_preset') or 'unchanged'}`",
        f"- Node group: `{mk8s_map.get('node_group') or 'all selected by node-template plan'}`",
        f"- Status: `{mk8s_map.get('status') or 'not-requested'}`",
    ]

    slurm = checkpoint.get("slurm")
    slurm_map = slurm if isinstance(slurm, Mapping) else {}
    drained_nodes = slurm_map.get("drained_nodes")
    slurm_lines = [
        f"- Job policy: `{slurm_map.get('job_policy') or 'not-run'}`",
        "- cxcli-owned drained nodes: "
        + (
            ", ".join(f"`{node}`" for node in drained_nodes)
            if isinstance(drained_nodes, list) and drained_nodes
            else "none"
        ),
    ]
    manual_command = _non_empty_text(slurm_map.get("restore_manual_command"))
    if manual_command:
        slurm_lines.append(f"- Manual recovery command: `{manual_command}`")

    populate_jail = checkpoint.get("populate_jail_refresh")
    populate_jail_map = populate_jail if isinstance(populate_jail, Mapping) else {}
    populate_result = populate_jail_map.get("result")
    populate_result_map = populate_result if isinstance(populate_result, Mapping) else {}
    populate_jail_lines = [
        f"- Mode: `{populate_jail_map.get('mode') or 'auto'}`",
        f"- Required: `{populate_jail_map.get('required')}`",
        f"- Status: `{populate_result_map.get('status') or populate_jail_map.get('status') or 'planned'}`",
        f"- Reason: {populate_result_map.get('reason') or populate_jail_map.get('reason') or 'not evaluated'}",
        f"- Target image: `{populate_result_map.get('target_image') or 'unknown'}`",
        f"- Job: `{populate_result_map.get('job_name') or 'unknown'}`",
        f"- Maintenance restored: `{populate_result_map.get('maintenance_restored')}`",
    ]
    populate_detail = _non_empty_text(populate_result_map.get("detail"))
    if populate_detail:
        populate_jail_lines.append(f"- Detail: {populate_detail}")

    comparison = checkpoint.get("config_comparison")
    comparison_map = comparison if isinstance(comparison, Mapping) else {}
    comparison_lines = []
    for label in ("post_mk8s", "postflight"):
        value = comparison_map.get(label)
        if isinstance(value, Mapping):
            comparison_lines.append(f"- `{label}`: `{value.get('status') or 'unknown'}`")
        else:
            comparison_lines.append(f"- `{label}`: `not-run`")

    markdown = "\n".join(
        [
            "# Soperator Upgrade Report",
            "",
            f"- Target: `{checkpoint.get('target_ref', '')}`",
            f"- Release: `{checkpoint.get('namespace', 'default')}/{checkpoint.get('release_name', '')}`",
            f"- Chart version: `{checkpoint.get('current_version') or 'unset'}` -> `{checkpoint.get('target_version') or 'unset'}`",
            f"- Status: `{checkpoint.get('status', 'unknown')}`",
            f"- Current phase: `{current_phase_id}`"
            f"{current_phase_stage_text}{current_phase_component_text} - {current_phase_comment}",
            f"- Checkpoint: `{checkpoint.get('checkpoint_path', '')}`",
            f"- JSON report: `{SOPERATOR_UPGRADE_REPORT_JSON_FILENAME}`",
            "",
            "## Phase History",
            "",
            *phase_history_lines,
            "",
            "## Soperator Discovery",
            "",
            *discovery_lines,
            "",
            "## Restore-Capable Backup",
            "",
            *backup_lines,
            "",
            "## MK8s Node Template Phase",
            "",
            *mk8s_lines,
            "",
            "## Slurm Drain And Jobs",
            "",
            *slurm_lines,
            "",
            "## Populate-Jail Refresh",
            "",
            *populate_jail_lines,
            "",
            "## Protected Config Comparison",
            "",
            *comparison_lines,
            "",
            "## ActiveChecks Lifecycle",
            "",
            (
                "- Result: checkpointed suspend/restore was required."
                if bool(activechecks_map.get("required"))
                else "- Result: no ActiveChecks suspend/restore was required."
            ),
            *snapshot_lines,
            "",
            *stage_fast_verification_markdown_lines(
                stage_verification_reports,
                empty_message="No managed upgrade stage verifications were recorded.",
            ),
            "",
            *safety_report_markdown_lines(
                checkpoint.get("upgrade_safety")
                if isinstance(checkpoint.get("upgrade_safety"), Mapping)
                else None
            ),
            "",
            "## Events",
            "",
            *event_lines,
            "",
        ]
    )
    _write_text_atomic(markdown_path, markdown)
    return markdown_path, json_path


def _soperator_upgrade_slurm_cluster_ref(
    payload: dict[str, Any],
    target: _HelmChartUpgradeTarget,
) -> str:
    row = _source_helm_chart_row(payload, target)
    cluster_name = str(read_component_path(row, "values.clusterName") or "").strip()
    return cluster_name or target.target_ref


def _suspend_live_soperator_activechecks(
    config: Any,
    paths: ProjectPaths,
    manifest: Mapping[str, Any],
    plan: _HelmChartUpgradePlan,
    *,
    source_payload: dict[str, Any],
) -> dict[str, Any]:
    selected_targets = _resolve_selected_deploy_targets(
        manifest,
        requested_target_ref=plan.target.target_ref,
        all_targets=False,
    )
    target = selected_targets[0] if selected_targets else None
    if target is None:
        return {
            "status": "skipped",
            "reason": f"target '{plan.target.target_ref}' was not found in the generated manifest",
        }
    namespace = plan.namespace or "default"
    cluster_ref = _soperator_upgrade_slurm_cluster_ref(source_payload, plan.target)
    patched: list[str] = []
    skipped: list[str] = []
    activecheck_job_names: list[str] = []
    with ExitStack() as stack:
        kube_env = _prepare_cluster_handoff_kube_env(
            config,
            paths,
            stack=stack,
            target=target,
            persist_local_kubeconfig=False,
            set_current_context=False,
        )
        completed = subprocess.run(
            [
                "kubectl",
                "-n",
                namespace,
                "get",
                "activechecks.slurm.nebius.ai",
                "-o",
                "json",
            ],
            env=_post_flux_subprocess_env(kube_env),
            timeout=60,
            capture_output=True,
            text=True,
        )
        if completed.returncode != 0:
            detail = _first_non_empty_line(completed.stderr or completed.stdout or "")
            raise RuntimeError(
                "Cannot suspend live Soperator ActiveChecks before upgrade: "
                f"{detail or 'ActiveCheck resources are not available'}"
            )
        try:
            payload = json.loads(completed.stdout or "{}")
        except json.JSONDecodeError as exc:
            raise RuntimeError(
                "Cannot suspend live Soperator ActiveChecks before upgrade: "
                "kubectl returned unreadable ActiveCheck JSON."
            ) from exc
        items = payload.get("items")
        if not isinstance(items, list):
            raise RuntimeError(
                "Cannot suspend live Soperator ActiveChecks before upgrade: "
                "kubectl returned no ActiveCheck item list."
            )
        for item in items:
            if not isinstance(item, Mapping):
                continue
            metadata = item.get("metadata")
            spec = item.get("spec")
            status = item.get("status")
            metadata_map = metadata if isinstance(metadata, Mapping) else {}
            spec_map = spec if isinstance(spec, Mapping) else {}
            status_map = status if isinstance(status, Mapping) else {}
            name = str(metadata_map.get("name") or "").strip()
            item_cluster_ref = str(spec_map.get("slurmClusterRefName") or "").strip()
            if not name:
                continue
            if cluster_ref and item_cluster_ref and item_cluster_ref != cluster_ref:
                skipped.append(name)
                continue
            k8s_status = status_map.get("k8sJobsStatus")
            k8s_status_map = k8s_status if isinstance(k8s_status, Mapping) else {}
            job_name = str(k8s_status_map.get("lastJobName") or "").strip()
            if job_name:
                activecheck_job_names.append(job_name)
            _run_post_flux_kubectl(
                [
                    "kubectl",
                    "-n",
                    namespace,
                    "patch",
                    "activechecks.slurm.nebius.ai",
                    name,
                    "--type=merge",
                    "-p",
                    json.dumps({"spec": {"suspend": True, "runAfterCreation": False}}),
                ],
                env=kube_env,
                timeout=120,
                retries=2,
                retry_delay_seconds=5.0,
                retry_stderr_markers=_KUBECTL_TRANSIENT_FAILURE_MARKERS,
            )
            patched.append(name)
        workload_cleanup = _delete_soperator_activecheck_workloads_in_namespace(
            namespace,
            env=kube_env,
            cluster_ref=cluster_ref,
            activecheck_job_names=activecheck_job_names,
        )
    return {
        "status": "suspended" if patched else "no_matching_activechecks",
        "namespace": namespace,
        "cluster_ref": cluster_ref,
        "patched": patched,
        "skipped": skipped,
        "workload_cleanup": workload_cleanup,
    }


def _soperator_upgrade_optional_service_notes(
    payload: dict[str, Any],
    target: _HelmChartUpgradeTarget,
) -> tuple[str, ...]:
    row = _source_helm_chart_row(payload, target)
    activechecks_enabled = read_component_path(row, "values.soperator-activechecks.enabled") is True
    checks_enabled = read_component_path(row, "values.soperator-checks.enabled") is True
    notes: list[str] = []
    if checks_enabled and not activechecks_enabled:
        notes.append(
            "The Soperator checks controller is enabled without ActiveChecks; it "
            "can still reconcile maintenance/degraded node conditions."
        )
    return tuple(notes)


def _format_soperator_upgrade_plan(
    plan: _HelmChartUpgradePlan,
    *,
    payload: dict[str, Any],
    dry_run: bool,
    repeat_dry_run_command: str | None = None,
) -> tuple[str, ...]:
    lines = list(
        _format_helm_chart_upgrade_plan(
            plan,
            dry_run=dry_run,
            repeat_dry_run_command=repeat_dry_run_command,
        )
    )
    lines[0] = "Soperator upgrade plan"
    lines.extend(
        [
            "- Soperator-aware gates:",
            "  - preflight runs the existing generated-bundle validation and a live Soperator/Slurm smoke validation before mutation.",
            "  - apply updates config.yaml, rerenders, validates the new bundle, and applies only the selected target Flux bundle.",
            (
                "  - postflight verifies the static Soperator chart version, reruns "
                "the required Soperator/Slurm smoke validation, and writes "
                "soperator-upgrade-report.md and soperator-upgrade-report.json."
            ),
        ]
    )
    lifecycle = _soperator_upgrade_activechecks_lifecycle(payload, plan.target)
    if plan.mutates and lifecycle.required:
        lines.append("- ActiveChecks upgrade lifecycle:")
        lines.append(
            "  - cxcli snapshots the current ActiveChecks config, writes a local "
            "checkpoint, suspends ActiveChecks and wait-for-active-checks for the "
            "upgrade window, then restores the original values after postflight."
        )
        lines.append(
            "  - the checkpointed stage also patches existing live ActiveCheck CRs "
            "to suspend launch-on-create checks, fails closed when live ActiveChecks "
            "cannot be inspected, and deletes matching already-launched check "
            "jobs/CronJobs/pods before upgrade smoke validation."
        )
    notes = _soperator_upgrade_optional_service_notes(payload, plan.target)
    if notes:
        lines.append("- Soperator optional-service notes:")
        lines.extend(f"  - {note}" for note in notes)
    return tuple(lines)


def _verify_helm_chart_upgrade_ready(
    config: Any,
    paths: ProjectPaths,
    manifest: Mapping[str, Any],
    plan: _HelmChartUpgradePlan,
) -> None:
    selected_targets = _resolve_selected_deploy_targets(
        manifest,
        requested_target_ref=plan.target.target_ref,
        all_targets=False,
    )
    target = selected_targets[0] if selected_targets else None
    if target is None:
        raise RuntimeError(
            f"Cannot verify Helm chart upgrade for {plan.target.selector}: "
            f"target '{plan.target.target_ref}' was not found in the generated deploy manifest."
        )
    _ensure_terraform_backend_ready(config, auto_auth_bootstrap=True)
    with ExitStack() as stack:
        kube_env = _prepare_cluster_handoff_kube_env(
            config,
            paths,
            stack=stack,
            target=target,
            persist_local_kubeconfig=False,
            set_current_context=False,
        )
        result = verify_helm_chart_ready(
            command_runner=SubprocessHelmCommandRunner(extra_env=kube_env),
            release_name=plan.release_name,
            namespace=plan.namespace or "default",
            expected_version=plan.target_version,
        )
    console.print(f"[green]{result.summary()}[/green]")


def _kubectl_json_for_upgrade(
    args: Sequence[str],
    *,
    extra_env: Mapping[str, str],
    description: str,
    timeout_seconds: int = 120,
) -> Mapping[str, Any]:
    env = os.environ.copy()
    env.update(extra_env)
    completed = subprocess.run(
        list(args),
        check=False,
        capture_output=True,
        text=True,
        env=env,
        timeout=timeout_seconds,
    )
    if completed.returncode != 0:
        detail = (completed.stderr or completed.stdout or "").strip()
        raise RuntimeError(f"{description} failed: {detail or completed.returncode}")
    try:
        payload = json.loads(completed.stdout or "{}")
    except json.JSONDecodeError as exc:
        raise RuntimeError(f"{description} did not return valid JSON.") from exc
    if not isinstance(payload, Mapping):
        raise RuntimeError(f"{description} did not return a JSON object.")
    return payload


def _soperator_upgrade_chart_label(version: str) -> str:
    return f"soperator-{version}".replace("+", "_")


def _resource_chart_label(payload: Mapping[str, Any]) -> str:
    metadata = payload.get("metadata")
    if not isinstance(metadata, Mapping):
        return ""
    labels = metadata.get("labels")
    if not isinstance(labels, Mapping):
        return ""
    return str(labels.get("helm.sh/chart") or "").strip()


def _reconcile_soperator_slurm_nodeaddrs(
    *,
    namespace: str,
    cluster_name: str,
    kube_env: Mapping[str, str],
) -> tuple[str, ...]:
    service_suffix = f"{cluster_name}-nodeset-svc.{namespace}.svc.cluster.local"
    script = f"""
set -euo pipefail
service_suffix={shlex.quote(service_suffix)}
scontrol reconfigure >/dev/null 2>&1 || true
mapfile -t nodes < <(sinfo -N -h -o "%N" | awk 'NF && !seen[$1]++')
for node in "${{nodes[@]}}"; do
  expected="${{node}}.${{service_suffix}}"
  current="$(scontrol show node "${{node}}" | tr '\\n' ' ' | sed -n 's/.* NodeAddr=\\([^ ]*\\).*/\\1/p')"
  if [[ -n "${{current}}" && "${{current}}" != "${{expected}}" ]]; then
    scontrol update NodeName="${{node}}" NodeAddr="${{expected}}"
    printf '%s: %s -> %s\\n' "${{node}}" "${{current}}" "${{expected}}"
  fi
done
"""
    env = os.environ.copy()
    env.update(kube_env)
    completed = subprocess.run(
        ["kubectl", "-n", namespace, "exec", "login-0", "--", "bash", "-lc", script],
        check=False,
        capture_output=True,
        text=True,
        env=env,
        timeout=180,
    )
    if completed.returncode != 0:
        detail = (completed.stderr or completed.stdout or "").strip()
        raise RuntimeError(
            "Could not reconcile Soperator Slurm worker NodeAddr values after "
            f"static chart apply: {detail or completed.returncode}"
        )
    return tuple(line.strip() for line in completed.stdout.splitlines() if line.strip())


def _verify_soperator_static_upgrade_ready(
    config: Any,
    paths: ProjectPaths,
    manifest: Mapping[str, Any],
    plan: _HelmChartUpgradePlan,
) -> None:
    selected_targets = _resolve_selected_deploy_targets(
        manifest,
        requested_target_ref=plan.target.target_ref,
        all_targets=False,
    )
    target = selected_targets[0] if selected_targets else None
    if target is None:
        raise RuntimeError(
            f"Cannot verify Soperator upgrade for {plan.target.selector}: "
            f"target '{plan.target.target_ref}' was not found in the generated deploy manifest."
        )
    validation_specs = _soperator_upgrade_validation_specs(
        manifest,
        target_ref=plan.target.target_ref,
    )
    validation = validation_specs[0]
    namespace = str(validation.get("namespace") or plan.namespace or "soperator").strip()
    cluster_name = str(validation.get("cluster_name") or plan.target.target_ref or "mk8s").strip()
    expected_label = _soperator_upgrade_chart_label(plan.target_version)

    _ensure_terraform_backend_ready(config, auto_auth_bootstrap=True)
    with ExitStack() as stack:
        kube_env = _prepare_cluster_handoff_kube_env(
            config,
            paths,
            stack=stack,
            target=target,
            persist_local_kubeconfig=False,
            set_current_context=False,
        )
        env = os.environ.copy()
        env.update(kube_env)
        rollout = subprocess.run(
            [
                "kubectl",
                "-n",
                namespace,
                "rollout",
                "status",
                "deployment/soperator-manager",
                "--timeout=10m",
            ],
            check=False,
            capture_output=True,
            text=True,
            env=env,
            timeout=660,
        )
        if rollout.returncode != 0:
            detail = (rollout.stderr or rollout.stdout or "").strip()
            raise RuntimeError(
                "Soperator manager deployment did not become ready after static "
                f"chart apply: {detail or rollout.returncode}"
            )

        checked: list[str] = []
        for resource, name in (
            ("deployment", "soperator-manager"),
            ("slurmcluster.slurm.nebius.ai", cluster_name),
        ):
            payload = _kubectl_json_for_upgrade(
                [
                    "kubectl",
                    "-n",
                    namespace,
                    "get",
                    resource,
                    name,
                    "-o",
                    "json",
                ],
                extra_env=kube_env,
                description=f"kubectl get {resource}/{name}",
            )
            actual_label = _resource_chart_label(payload)
            if actual_label != expected_label:
                raise RuntimeError(
                    f"Soperator static chart version check failed for {resource}/{name}: "
                    f"expected helm.sh/chart={expected_label}, got "
                    f"{actual_label or '<missing>'}."
                )
            checked.append(f"{resource}/{name}")
        reconciled = _reconcile_soperator_slurm_nodeaddrs(
            namespace=namespace,
            cluster_name=cluster_name,
            kube_env=kube_env,
        )
    console.print(
        "[green]Soperator static chart version verified: "
        f"{expected_label} on {', '.join(checked)}[/green]"
    )
    if reconciled:
        console.print(
            "[green]Reconciled Soperator Slurm worker NodeAddr values: "
            f"{'; '.join(reconciled)}[/green]",
            soft_wrap=True,
        )


def _soperator_upgrade_validation_specs(
    manifest: Mapping[str, Any],
    *,
    target_ref: str,
) -> list[dict[str, Any]]:
    validations = _filter_validations_for_target(
        _manifest_deploy_validations(manifest),
        target_ref=target_ref,
    )
    selected = [
        dict(item)
        for item in validations
        if str(item.get("kind", "") or "").strip() == SOPERATOR_CLUSTER_VALIDATION_KIND
    ]
    if not selected:
        raise RuntimeError(
            f"Cannot run Soperator upgrade validation for target '{target_ref}': "
            "the generated manifest does not declare the required "
            f"{SOPERATOR_CLUSTER_VALIDATION_KIND} validation. Rerender with "
            "`nebius-cxcli render <config.yaml>` before upgrading."
        )
    return selected


def _run_soperator_upgrade_validation_phase(
    config: Any,
    paths: ProjectPaths,
    manifest: Mapping[str, Any],
    plan: _HelmChartUpgradePlan,
    *,
    phase_label: str,
    persist_reports: bool,
) -> tuple[Path, ...]:
    selected_targets = _resolve_selected_deploy_targets(
        manifest,
        requested_target_ref=plan.target.target_ref,
        all_targets=False,
    )
    target = selected_targets[0] if selected_targets else None
    if target is None:
        raise RuntimeError(
            f"Cannot run Soperator upgrade validation for {plan.target.selector}: "
            f"target '{plan.target.target_ref}' was not found in the generated deploy manifest."
        )
    validations = _soperator_upgrade_validation_specs(
        manifest,
        target_ref=plan.target.target_ref,
    )
    with ExitStack() as stack:
        kube_env = _prepare_cluster_handoff_kube_env(
            config,
            paths,
            stack=stack,
            target=target,
            persist_local_kubeconfig=False,
            set_current_context=False,
        )
        with console.status(
            f"[cyan]{phase_label} Soperator/Slurm validation for {plan.target.target_ref}...[/cyan]",
            spinner="dots",
        ) as status:
            last_validation_phase = ""

            def _emit_validation_phase(message: str) -> None:
                nonlocal last_validation_phase
                status.update(message)
                if not _console_is_terminal() and message != last_validation_phase:
                    console.print(message)
                last_validation_phase = message

            if persist_reports:
                paths.reports_dir.mkdir(parents=True, exist_ok=True)
                clear_deploy_validation_artifacts(
                    validations,
                    reports_dir=paths.reports_dir,
                    include_markdown=False,
                )
                reports_dir = paths.reports_dir
            else:
                temp_dir = stack.enter_context(
                    tempfile.TemporaryDirectory(prefix="nebius-cxcli-soperator-upgrade-preflight-")
                )
                reports_dir = Path(temp_dir)
            written_reports = _run_deploy_validations(
                validations,
                reports_dir=reports_dir,
                extra_env=kube_env,
                emit=_emit_validation_phase,
            )
    return tuple(written_reports) if persist_reports else ()


def _raise_if_soperator_upgrade_would_bypass_migration(
    config: Any,
    *,
    config_path: Path,
    manifest: Mapping[str, Any],
    target_ref: str,
) -> None:
    selected_targets = _resolve_selected_deploy_targets(
        manifest,
        requested_target_ref=target_ref,
        all_targets=False,
    )
    _raise_if_deploy_would_bypass_soperator_migration(
        config,
        config_path=config_path,
        selected_targets=selected_targets,
    )


def _status_watchers_for_component(
    watchers: Sequence[Mapping[str, Any]],
    *,
    component_id: str,
    instance_id: str,
) -> list[dict[str, str]]:
    normalized_component = normalize_component_token(component_id)
    normalized_instance = normalize_component_token(instance_id)
    return [
        dict(watcher)
        for watcher in watchers
        if normalize_component_token(watcher.get("component_id")) == normalized_component
        and normalize_component_token(watcher.get("instance_id")) == normalized_instance
    ]


def _print_upgrade_plan_lines(lines: Sequence[str]) -> None:
    in_warnings = False
    in_copy_paste_command = False
    for line in lines:
        if line == "- warnings:":
            in_warnings = True
            in_copy_paste_command = False
            console.print(f"- {warning_markup('warnings:', bold=True)}")
            continue
        if in_warnings and line.startswith("  - "):
            console.print(f"  - {warning_markup(line[4:])}")
            continue
        if line in {"- repeat dry-run command:", "- approved execute command:"}:
            in_warnings = False
            in_copy_paste_command = True
            console.print(line)
            continue
        if in_copy_paste_command and line.strip().startswith("nebius-cxcli "):
            _print_copy_paste_command(line)
            continue
        in_warnings = False
        in_copy_paste_command = False
        console.print(line)


def _upgrade_strategy_restore_after_wait(
    *,
    temporary_strategy: Mapping[str, Any] | None,
    rollout_incomplete: bool,
    source_sync_required: bool,
) -> bool:
    return bool(temporary_strategy is not None and rollout_incomplete and not source_sync_required)


def _upgrade_planned_stage_count(
    *,
    control_plane_stage_count: int = 0,
    node_group_stage_count: int,
    source_sync_required: bool,
    strategy_restore_after_wait: bool,
    temporary_strategy: Mapping[str, Any] | None,
) -> tuple[int, list[str]]:
    planned_stage_count = control_plane_stage_count + node_group_stage_count
    extra_stage_summaries: list[str] = []
    if planned_stage_count == 0 and source_sync_required:
        planned_stage_count = 1
        extra_stage_summaries.append("1 source-sync stage")
    elif planned_stage_count == 0 and strategy_restore_after_wait:
        planned_stage_count = 1
        extra_stage_summaries.append("1 strategy-restore stage")
    elif temporary_strategy is not None and node_group_stage_count:
        planned_stage_count += 1
        extra_stage_summaries.append("1 strategy-restore stage")
    return planned_stage_count, extra_stage_summaries


def _upgrade_strategy_restore_required(
    *,
    strategy_restore_after_wait: bool,
    waited_for_existing_rollout: bool,
    stage_applied: bool,
) -> bool:
    return bool(strategy_restore_after_wait and waited_for_existing_rollout and not stage_applied)


def _upgrade_final_stage_title(
    *,
    strategy_restored: bool,
    strategy_restore_required: bool,
    source_sync_title: str,
) -> str:
    if strategy_restored or strategy_restore_required:
        return "node-group strategy restore"
    return source_sync_title


def _quota_identity_from_payload(
    payload: Mapping[str, Any],
    generated_config: Any,
) -> tuple[str, str, str]:
    client_info = payload.get("client_info")
    nebius = client_info.get("nebius") if isinstance(client_info, Mapping) else None
    generated_nebius = getattr(getattr(generated_config, "client_info", None), "nebius", None)
    tenant_id = _non_empty_text(
        nebius.get("tenant_id") if isinstance(nebius, Mapping) else None
    ) or _non_empty_text(getattr(generated_nebius, "tenant_id", None))
    project_id = _non_empty_text(
        nebius.get("project_id") if isinstance(nebius, Mapping) else None
    ) or _non_empty_text(getattr(generated_nebius, "project_id", None))
    region_id = _non_empty_text(
        nebius.get("region_id") if isinstance(nebius, Mapping) else None
    ) or _non_empty_text(getattr(generated_nebius, "region_id", None))
    return tenant_id, project_id, region_id


def _max_quota_requirements_by_name_region_shape(
    requirements: Sequence[QuotaRequirement],
) -> tuple[QuotaRequirement, ...]:
    by_key: dict[tuple[str, str, Any], QuotaRequirement] = {}
    for item in requirements:
        key = (item.quota_name, item.region, item.gpu_capacity_shape)
        existing = by_key.get(key)
        if existing is None or item.required > existing.required:
            by_key[key] = item
    return tuple(
        by_key[key]
        for key in sorted(
            by_key,
            key=lambda value: (value[1], value[0], str(value[2])),
        )
    )


def _node_template_safe_surge_group_payload(
    source_component: Mapping[str, Any],
    group: LiveNodeGroup,
    *,
    max_surge_count: int,
) -> dict[str, Any]:
    inputs = source_component.get("inputs")
    source_groups = inputs.get("node_groups") if isinstance(inputs, Mapping) else None
    raw_group = (
        source_groups.get(group.source.key)
        if isinstance(source_groups, Mapping) and group.source is not None
        else None
    )
    payload = copy.deepcopy(to_plain_data(raw_group)) if isinstance(raw_group, Mapping) else {}
    payload["enabled"] = True
    payload["node_count"] = max_surge_count
    payload.pop("autoscaling", None)
    payload.setdefault("gpu", group.gpu)
    payload.setdefault("platform", group.platform)
    payload.setdefault("preset", group.preset)
    if group.source is not None:
        if group.source.gpu_cluster_key and not payload.get("gpu_cluster_key"):
            payload["gpu_cluster_key"] = group.source.gpu_cluster_key
        if group.source.gpu_stack_source and not payload.get("gpu_stack_source"):
            payload["gpu_stack_source"] = group.source.gpu_stack_source
        reservation = payload.get("reservation")
        if not isinstance(reservation, Mapping):
            reservation = {}
        else:
            reservation = copy.deepcopy(to_plain_data(reservation))
        if group.source.reservation_policy and not reservation.get("policy"):
            reservation["policy"] = group.source.reservation_policy
        if group.source.reservation_ids and not reservation.get("reservation_ids"):
            reservation["reservation_ids"] = list(group.source.reservation_ids)
        if reservation:
            payload["reservation"] = reservation
    return payload


def _node_template_safe_surge_group_fabric(
    source_component: Mapping[str, Any],
    group: LiveNodeGroup,
) -> str:
    if group.source is None or not group.source.gpu_cluster_key:
        return ""
    source_inputs = source_component.get("inputs")
    gpu_clusters = source_inputs.get("gpu_clusters") if isinstance(source_inputs, Mapping) else None
    cluster = (
        gpu_clusters.get(group.source.gpu_cluster_key)
        if isinstance(gpu_clusters, Mapping)
        else None
    )
    if not isinstance(cluster, Mapping):
        return ""
    return _non_empty_text(cluster.get("infiniband_fabric"))


def _node_template_safe_surge_reservation_policy(planned_group: Mapping[str, Any]) -> str:
    reservation = planned_group.get("reservation")
    if isinstance(reservation, Mapping):
        return _non_empty_text(reservation.get("policy")).upper()
    return ""


def _node_template_safe_surge_quota_requirements(
    *,
    source_component: Mapping[str, Any],
    plan: Mk8sNodeTemplateUpgradePlan,
    project_id: str,
    region_id: str,
    max_surge_count: int,
    request_groups: Sequence[LiveNodeGroup],
) -> tuple[tuple[QuotaRequirement, ...], tuple[QuotaCoverageGap, ...], tuple[str, ...]]:
    requirements: list[QuotaRequirement] = []
    coverage_gaps: list[QuotaCoverageGap] = []
    lines: list[str] = []
    source_inputs = source_component.get("inputs")
    shared_inputs: dict[str, Any] = {}
    if isinstance(source_inputs, Mapping):
        for key in ("gpu_clusters", "node_group_defaults"):
            value = source_inputs.get(key)
            if isinstance(value, Mapping):
                shared_inputs[key] = copy.deepcopy(to_plain_data(value))
    for group in request_groups:
        if group.source is None:
            continue
        planned_name = (
            f"{plan.cluster_name or plan.target.instance_id}-{group.source.key}-safe-surge"
        )
        planned_group = _node_template_safe_surge_group_payload(
            source_component,
            group,
            max_surge_count=max_surge_count,
        )
        fabric = _node_template_safe_surge_group_fabric(source_component, group)
        has_gpu_cluster = bool(group.source.gpu_cluster_key or group.source.gpu_cluster_id)
        if group.gpu and has_gpu_cluster and not fabric:
            instance_id = f"{plan.target.instance_id}-node-template-surge-{group.source.key}"
            fabric_source = (
                f"inputs.gpu_clusters.{group.source.gpu_cluster_key}.infiniband_fabric"
                if group.source.gpu_cluster_key
                else f"gpu_cluster_id {group.source.gpu_cluster_id}"
            )
            coverage_gaps.append(
                QuotaCoverageGap(
                    component_id=MK8S_COMPONENT_ID,
                    instance_id=instance_id,
                    component_label=component_instance_label(MK8S_COMPONENT_ID, instance_id),
                    message=(
                        "safe-surge cannot verify GPU Capacity Dashboard availability on the "
                        f"same fabric for node group '{group.name}' because "
                        f"{fabric_source} does not resolve to an infiniband_fabric in config"
                    ),
                )
            )
            continue
        estimate_inputs = {
            **shared_inputs,
            "node_groups": {planned_name: planned_group},
        }
        group_requirements, group_gaps = estimate_mk8s_quota_requirements(
            project_id=project_id,
            region=region_id,
            instance_id=f"{plan.target.instance_id}-node-template-surge-{group.source.key}",
            inputs=estimate_inputs,
            context="node-template safe-surge quota preflight",
        )
        requirements.extend(
            item for item in group_requirements if item.quota_name != "mk8s.cluster.count"
        )
        coverage_gaps.extend(group_gaps)
        role = "gpu" if group.gpu else "cpu/system"
        fabric_suffix = f", fabric {fabric}" if group.gpu and fabric else ""
        reservation_policy = _node_template_safe_surge_reservation_policy(planned_group)
        reservation_suffix = (
            f", reservation policy {reservation_policy}" if group.gpu and reservation_policy else ""
        )
        lines.append(
            "Safe-surge quota preflight: "
            f"{group.name} requires {max_surge_count} temporary surge node(s) "
            f"at {group.platform or 'unknown-platform'}/{group.preset or 'unknown-preset'}"
            f"{fabric_suffix}{reservation_suffix} "
            f"({role})."
        )
    return (
        _max_quota_requirements_by_name_region_shape(requirements),
        tuple(coverage_gaps),
        tuple(lines),
    )


def _node_template_safe_surge_quota_failure_message(report: QuotaReport) -> str:
    detail_lines = format_quota_report_lines(
        report,
        phase="node-template safe-surge",
        include_coverage_gaps=True,
        include_confirmed_components=True,
        markup=False,
    )
    details = "\n".join(detail_lines).strip()
    if not details:
        details = "live quota/capacity could not be confirmed for the safe-surge plan"
    return (
        "Node-template safe-surge quota preflight failed before any staged mutation. "
        "Resolve confirmed quota/capacity shortages, unresolved quota/capacity limits, "
        "quota coverage gaps, or lookup errors before rerunning upgrade node-template. "
        "GPU safe-surge capacity is checked on the same fabric and reservation policy "
        "as the selected node group; use capacity on that fabric, use zero-surge, or "
        "migrate to a new GPU node group/fabric before retrying.\n" + details
    )


def _run_node_template_safe_surge_quota_preflight(
    *,
    source_payload: Mapping[str, Any],
    generated_config: Any,
    source_component: Mapping[str, Any],
    plan: Mk8sNodeTemplateUpgradePlan,
    max_surge_count: int,
    request_groups: Sequence[LiveNodeGroup],
) -> QuotaReport:
    tenant_id, project_id, region_id = _quota_identity_from_payload(
        source_payload,
        generated_config,
    )
    if not request_groups:
        report = QuotaReport(
            tenant_id=tenant_id,
            project_id=project_id,
            region_id=region_id,
            checked_at=datetime.now(UTC).isoformat(),
        )
        console.print("Safe-surge quota preflight: no new node-group surge quota is required.")
        return report
    requirements, coverage_gaps, plan_lines = _node_template_safe_surge_quota_requirements(
        source_component=source_component,
        plan=plan,
        project_id=project_id,
        region_id=region_id,
        max_surge_count=max_surge_count,
        request_groups=request_groups,
    )
    for line in plan_lines:
        console.print(line)
    if not requirements and not coverage_gaps:
        report = QuotaReport(
            tenant_id=tenant_id,
            project_id=project_id,
            region_id=region_id,
            checked_at=datetime.now(UTC).isoformat(),
        )
    else:
        report = assess_live_quota_requirements(
            tenant_id=tenant_id,
            project_id=project_id,
            region_id=region_id,
            requirements=requirements,
            coverage_gaps=coverage_gaps,
            context="node-template safe-surge quota preflight",
        )
    if (
        report.has_confirmed_insufficiency
        or report.unknown_checks
        or report.coverage_gaps
        or report.errors
    ):
        raise RuntimeError(_node_template_safe_surge_quota_failure_message(report))
    for line in format_quota_report_lines(
        report,
        phase="node-template safe-surge",
        include_coverage_gaps=True,
        include_confirmed_components=True,
    ):
        console.print(line)
    if report.sufficient_checks:
        console.print(
            "Safe-surge quota preflight: all checked temporary surge quota/capacity "
            "requirements are sufficient."
        )
    return report


@upgrade_app.command(
    "node-template",
    short_help=(
        "Upgrade MK8s Kubernetes version, OS image, or GPU stack values through "
        "one node-template rolling-update path."
    ),
    epilog=_UPGRADE_NODE_TEMPLATE_EPILOG,
)
def upgrade_node_template_command(
    config_path: Annotated[
        Path,
        typer.Argument(metavar="CONFIG_YAML", help=_CONFIG_YAML_ARGUMENT_HELP),
    ],
    target_selector: Annotated[
        str | None,
        typer.Argument(
            metavar="TARGET",
            help=(
                "Optional target selector, for example infra:mk8s@mk8s. "
                "Omit to choose from Terraform-managed MK8s targets interactively."
            ),
        ),
    ] = None,
    to_version: Annotated[
        str | None,
        typer.Option(
            "--to-version",
            help="Target Kubernetes major.minor version, for example 1.33.",
        ),
    ] = None,
    to_os: Annotated[
        str | None,
        typer.Option(
            "--to-os",
            help="Target MK8s node template OS value, for example ubuntu24.04.",
        ),
    ] = None,
    to_gpu_stack_preset: Annotated[
        str | None,
        typer.Option(
            "--to-gpu-stack-preset",
            help=(
                "Target Nebius GPU stack/drivers_preset value, for example cuda13.0. "
                "Required when selected groups include Nebius-image GPU groups."
            ),
        ),
    ] = None,
    node_group: Annotated[
        str,
        typer.Option("--node-group", help="Optional concrete node-group name to upgrade."),
    ] = "",
    dry_run: Annotated[
        bool,
        typer.Option("--dry-run", help="Print the upgrade plan without writing files or applying."),
    ] = False,
    disruption_policy: Annotated[
        str,
        typer.Option(
            "--strategy",
            help="Upgrade strategy: zero-surge, safe-surge, or force-delete.",
        ),
    ] = DISRUPTION_POLICY_ALLOW_UNAVAILABLE,
    drain_timeout: Annotated[
        str,
        typer.Option(
            "--drain-timeout",
            help="Node drain timeout: auto, none, or a Go-style duration such as 10m.",
        ),
    ] = "auto",
    strategy_max_surge_count: Annotated[
        int | None,
        typer.Option(
            "--strategy-max-surge-count",
            help=(
                "Temporary extra nodes per active node group for --strategy safe-surge. Default: 1."
            ),
        ),
    ] = None,
    auto_auth_bootstrap: Annotated[
        bool,
        typer.Option(
            "--auto-auth-bootstrap/--no-auto-auth-bootstrap",
            help="Automatically bootstrap runtime auth material for generated-bundle validation.",
        ),
    ] = True,
    skip_validations: Annotated[
        bool,
        typer.Option(
            "--skip-validations",
            help="Skip optional post-upgrade deploy validations; required generated validations still run.",
        ),
    ] = False,
    skip_validation: Annotated[
        list[str] | None,
        typer.Option(
            "--skip-validation",
            help="Skip one optional post-upgrade validation kind; repeatable.",
        ),
    ] = None,
    interactive: Annotated[
        bool,
        typer.Option(
            "--interactive/--no-interactive",
            help="Prompt for missing node-template upgrade flags when running from a terminal.",
        ),
    ] = True,
) -> None:
    """Upgrade MK8s Kubernetes version, OS image, or GPU stack values."""

    sdk: Any | None = None
    warning_cache_token = _DEPLOY_VALIDATION_WARNING_CACHE.set(set())
    try:
        target_missing = not _non_empty_text(target_selector)
        requested_template_change = any(
            _non_empty_text(value) for value in (to_version, to_os, to_gpu_stack_preset)
        )
        prompt_all_template_fields = interactive and not requested_template_change
        guided = target_missing or prompt_all_template_fields
        if not interactive:
            missing = []
            if target_missing:
                missing.append("target selector")
            if not requested_template_change:
                missing.append(
                    "one of --to-version <major.minor>, --to-os <os>, or "
                    "--to-gpu-stack-preset <preset>"
                )
            if missing:
                raise RuntimeError(
                    "Missing "
                    + " and ".join(missing)
                    + ". Pass explicit upgrade options or allow interactive prompting."
                )
        if not guided:
            initial_policy = validate_disruption_policy(disruption_policy)
            resolve_drain_timeout(initial_policy, drain_timeout)
            resolve_strategy_max_surge_count(initial_policy, strategy_max_surge_count)

        source_payload = _load_source_payload(config_path)
        generated_config, paths, manifest = _load_deploy_context_readonly(config_path)
        project_id = str(generated_config.client_info.nebius.project_id).strip()
        sdk = init_nebius_sdk(
            parent_id=project_id or None,
            endpoint=_non_empty_text(os.environ.get("NEBIUS_ENDPOINT")) or None,
            context="MK8s node-template upgrade",
            prefer_operator_auth=True,
        )
        executor = Mk8sKubernetesVersionExecutor(sdk)

        prompt_target = target_missing
        prompt_to_version = prompt_all_template_fields and not _non_empty_text(to_version)
        prompt_node_group = guided and not _non_empty_text(node_group)
        prompt_to_os = prompt_all_template_fields and not _non_empty_text(to_os)
        prompted_setup_steps: list[str] = []
        setup_steps = (
            "target",
            "to_version",
            "node_group",
            "to_os",
            "to_gpu_stack_preset",
            "disruption",
        )
        setup_step_index = 0

        resolved_selector = ""
        target: Any | None = None
        source_component: Mapping[str, Any] | None = None
        selected_target: Mapping[str, Any] | None = None
        cluster: Any | None = None
        cluster_id = ""
        supported_versions: tuple[str, ...] = ()
        live_node_groups: tuple[Any, ...] = ()
        normalized_to_version = ""
        target_os = ""
        target_gpu_stack_preset = (
            validate_node_template_field_value(
                str(to_gpu_stack_preset),
                flag_name="--to-gpu-stack-preset",
            )
            if _non_empty_text(to_gpu_stack_preset)
            else ""
        )

        def _setup_backtrack() -> None:
            nonlocal setup_step_index
            if not prompted_setup_steps:
                raise RuntimeError("Upgrade wizard cancelled.")
            previous_step = prompted_setup_steps.pop()
            setup_step_index = setup_steps.index(previous_step)

        while setup_step_index < len(setup_steps):
            setup_step = setup_steps[setup_step_index]
            if setup_step == "target":
                prompted_selector = _prompt_upgrade_mk8s_target_selector_or_back_if_needed(
                    manifest=manifest,
                    target_selector=target_selector,
                    path_label="upgrade.node_template.target",
                )
                if _wizard_backtrack_requested(prompted_selector):
                    _setup_backtrack()
                    continue
                resolved_selector = str(prompted_selector or "").strip()
                target = parse_upgrade_selector(resolved_selector)
                source_component = find_source_mk8s_component(source_payload, target.instance_id)
                selected_target = _resolve_managed_mk8s_upgrade_target(
                    manifest,
                    target_instance_id=target.instance_id,
                )
                cluster_name = source_mk8s_cluster_name(
                    source_component,
                    fallback=target.instance_id,
                )
                try:
                    cluster = executor.get_cluster_by_name(project_id=project_id, name=cluster_name)
                except Exception as exc:
                    raise RuntimeError(
                        f"Could not find live MK8s cluster '{cluster_name}' in project "
                        f"'{project_id}'. Deploy the generated MK8s infrastructure before "
                        "running upgrade node-template."
                    ) from exc
                cluster_id = _live_mk8s_cluster_id(cluster, cluster_name=cluster_name)
                selected_target = _managed_mk8s_target_with_cluster_id(
                    selected_target,
                    cluster_id=cluster_id,
                )
                supported_versions = tuple(executor.control_plane_versions())
                if prompt_target:
                    prompted_setup_steps.append(setup_step)
                setup_step_index += 1
                continue
            if setup_step == "to_version":
                if cluster is None:
                    raise RuntimeError("Upgrade wizard did not resolve a live MK8s cluster.")
                if prompt_to_version:
                    prompted_version = _prompt_upgrade_node_template_to_version_or_back_if_needed(
                        cluster=cluster,
                        cluster_id=cluster_id,
                        supported_versions=supported_versions,
                        to_version=to_version,
                        path_label="upgrade.node_template.to_version",
                    )
                    if _wizard_backtrack_requested(prompted_version):
                        _setup_backtrack()
                        continue
                    normalized_to_version = str(prompted_version or "").strip()
                elif _non_empty_text(to_version):
                    normalized_to_version = parse_k8s_version(str(to_version)).minor_text
                else:
                    normalized_to_version = _cluster_control_plane_minor_version(
                        cluster,
                        cluster_id=cluster_id,
                    )
                supported_minors = {
                    parse_k8s_version(version).minor_text for version in supported_versions
                }
                if supported_minors and normalized_to_version not in supported_minors:
                    raise RuntimeError(
                        f"Kubernetes {normalized_to_version} is not currently listed by the Nebius "
                        "MK8s control-plane version API. Available versions: "
                        + ", ".join(sorted(supported_minors))
                    )
                if prompt_to_version:
                    prompted_setup_steps.append(setup_step)
                setup_step_index += 1
                continue
            if setup_step == "node_group":
                live_node_groups = executor.list_node_groups(cluster_id)
                prompted_node_group = _prompt_upgrade_node_group_if_guided(
                    path_prefix="upgrade.node_template",
                    guided=prompt_node_group,
                    node_group="" if prompt_node_group else node_group,
                    allow_backtrack=True,
                )
                if _wizard_backtrack_requested(prompted_node_group):
                    _setup_backtrack()
                    continue
                node_group = _non_empty_text(prompted_node_group)
                if prompt_node_group:
                    prompted_setup_steps.append(setup_step)
                setup_step_index += 1
                continue
            if setup_step == "to_os":
                if source_component is None:
                    raise RuntimeError("Upgrade wizard did not resolve a source MK8s component.")
                if not _non_empty_text(to_gpu_stack_preset):
                    target_gpu_stack_preset = ""
                selected_live_groups = _selected_node_template_live_groups(
                    source_component=source_component,
                    live_node_groups=live_node_groups,
                    node_group=node_group,
                )
                if prompt_to_os:
                    os_choices = node_template_os_choices(
                        source_component=source_component,
                        target_version=normalized_to_version,
                        target_gpu_stack_preset=target_gpu_stack_preset,
                        live_node_groups=live_node_groups,
                        node_group=node_group,
                        compatibility_lookup=executor.compatibility_choices,
                    )
                    prompted_os = _prompt_upgrade_node_template_to_os_if_needed(
                        path_label="upgrade.node_template.to_os",
                        to_os=to_os,
                        choices=os_choices,
                        allow_backtrack=True,
                    )
                    if _wizard_backtrack_requested(prompted_os):
                        _setup_backtrack()
                        continue
                    target_os = str(prompted_os or "").strip()
                    prompted_setup_steps.append(setup_step)
                elif _non_empty_text(to_os):
                    target_os = validate_os_image_value(str(to_os))
                else:
                    target_os = validate_os_image_value(
                        _single_selected_live_value(
                            selected_live_groups,
                            attr="os",
                            option_name="--to-os",
                            value_label="OS image",
                        )
                    )
                setup_step_index += 1
                continue
            if setup_step == "to_gpu_stack_preset":
                if source_component is None:
                    raise RuntimeError("Upgrade wizard did not resolve a source MK8s component.")
                selected_live_groups = _selected_node_template_live_groups(
                    source_component=source_component,
                    live_node_groups=live_node_groups,
                    node_group=node_group,
                )
                gpu_stack_required = any(
                    node_group_uses_nebius_gpu_image(group) for group in selected_live_groups
                )
                prompt_gpu_stack = (
                    prompt_all_template_fields
                    and gpu_stack_required
                    and not _non_empty_text(to_gpu_stack_preset)
                )
                if prompt_gpu_stack:
                    prompted_gpu_stack = _prompt_upgrade_node_template_field_value_if_needed(
                        path_label="upgrade.node_template.to_gpu_stack_preset",
                        value=to_gpu_stack_preset,
                        option_name="--to-gpu-stack-preset",
                        choices=node_template_gpu_stack_choices(
                            source_component=source_component,
                            target_version=normalized_to_version,
                            target_os=target_os,
                            live_node_groups=live_node_groups,
                            node_group=node_group,
                            compatibility_lookup=executor.compatibility_choices,
                        ),
                        allow_backtrack=True,
                    )
                    if _wizard_backtrack_requested(prompted_gpu_stack):
                        _setup_backtrack()
                        continue
                    target_gpu_stack_preset = str(prompted_gpu_stack or "").strip()
                    prompted_setup_steps.append(setup_step)
                else:
                    target_gpu_stack_preset = _default_node_template_gpu_stack_preset(
                        selected_live_groups,
                        to_gpu_stack_preset=to_gpu_stack_preset,
                        prompt_gpu_stack=prompt_gpu_stack,
                    )
                setup_step_index += 1
                continue
            if setup_step == "disruption":
                prompted_disruption = _prompt_upgrade_disruption_options_if_guided(
                    path_prefix="upgrade.node_template",
                    guided=guided,
                    dry_run=dry_run,
                    disruption_policy=disruption_policy,
                    drain_timeout=drain_timeout,
                    strategy_max_surge_count=strategy_max_surge_count,
                    skip_validations=skip_validations,
                    allow_outer_backtrack=True,
                )
                if _wizard_backtrack_requested(prompted_disruption):
                    _setup_backtrack()
                    continue
                (
                    dry_run,
                    disruption_policy,
                    drain_timeout,
                    strategy_max_surge_count,
                    skip_validations,
                ) = prompted_disruption
                setup_step_index += 1
                continue
            setup_step_index += 1

        if target is None or source_component is None or selected_target is None or cluster is None:
            raise RuntimeError("Upgrade wizard did not resolve the MK8s node-template target.")
        policy = validate_disruption_policy(disruption_policy)
        resolved_timeout = resolve_drain_timeout(policy, drain_timeout)
        resolved_max_surge_count = strategy_max_surge_count
        with ExitStack() as stack:
            with _upgrade_discovery_status(
                "[cyan]Discovering live MK8s state and preparing node-template upgrade plan...[/cyan]"
            ):
                kube_env = _prepare_cluster_handoff_kube_env(
                    generated_config,
                    paths,
                    stack=stack,
                    target=selected_target,
                    persist_local_kubeconfig=False,
                    set_current_context=False,
                )
                preflight_findings = collect_kubernetes_preflight_findings(kube_env=kube_env)
                plan = plan_node_template_upgrade(
                    target=target,
                    cluster=cluster,
                    cluster_id=cluster_id,
                    source_component=source_component,
                    target_version=normalized_to_version,
                    target_os=target_os,
                    target_gpu_stack_preset=target_gpu_stack_preset,
                    disruption_policy=policy,
                    drain_timeout=resolved_timeout,
                    strategy_max_surge_count=resolved_max_surge_count,
                    live_node_groups=live_node_groups,
                    compatibility_lookup=executor.compatibility_choices,
                    node_group=_non_empty_text(node_group),
                    preflight_findings=preflight_findings,
                )
                repeat_dry_run_command = (
                    _upgrade_node_template_dry_run_command(
                        config_path=config_path,
                        target_selector=target.selector,
                        to_version=normalized_to_version,
                        to_os=target_os,
                        to_gpu_stack_preset=target_gpu_stack_preset,
                        node_group=_non_empty_text(node_group),
                        disruption_policy=policy,
                        drain_timeout=resolved_timeout,
                        strategy_max_surge_count=resolved_max_surge_count,
                        auto_auth_bootstrap=auto_auth_bootstrap,
                        skip_validations=skip_validations,
                        skip_validation=skip_validation,
                    )
                    if dry_run
                    else None
                )
            _print_upgrade_plan_lines(
                format_node_template_upgrade_plan(
                    plan,
                    dry_run=dry_run,
                    repeat_dry_run_command=repeat_dry_run_command,
                )
            )

            if dry_run:
                return
            if plan.compatibility_failures:
                raise RuntimeError(
                    "Node-template upgrade is blocked by the live Nebius MK8s "
                    "compatibility matrix. Choose compatible --to-version, --to-os, "
                    "and --to-gpu-stack-preset values, then rerun upgrade node-template."
                )

            selected_group_keys = tuple(
                group.source.key for group in plan.node_groups if group.source is not None
            )
            current_group_versions = source_node_group_versions_for_groups(plan.all_node_groups)
            desired_group_versions = dict(current_group_versions)
            final_group_versions = dict(current_group_versions)
            for planned_group in plan.node_groups:
                if planned_group.source is not None:
                    final_group_versions[planned_group.source.key] = normalized_to_version

            source_sync_payload = copy.deepcopy(source_payload)
            source_sync_required = update_source_node_template(
                source_sync_payload,
                instance_id=target.instance_id,
                target_version=normalized_to_version,
                target_os=target_os,
                target_gpu_stack_preset=target_gpu_stack_preset,
                node_group_keys=selected_group_keys,
                node_group_versions=final_group_versions,
            )

            def _node_template_request_needed(planned_group: LiveNodeGroup) -> bool:
                target_drivers_preset = node_template_target_drivers_preset(
                    planned_group,
                    target_gpu_stack_preset=target_gpu_stack_preset,
                )
                live_driver_matches = (
                    target_drivers_preset is None
                    or planned_group.drivers_preset == target_drivers_preset
                )
                return (
                    parse_k8s_version(planned_group.version).minor_text != normalized_to_version
                    or planned_group.os != target_os
                    or not live_driver_matches
                )

            if plan.mutates:
                blockers = blocking_preflight_findings(
                    plan.preflight_findings,
                    disruption_policy=policy,
                )
                if blockers:
                    blocker_labels = ", ".join(
                        f"{finding.kind}:{finding.namespace}/{finding.name}" for finding in blockers
                    )
                    raise RuntimeError(
                        f"Upgrade preflight blockers must be resolved first: {blocker_labels}"
                    )
                if policy == DISRUPTION_POLICY_SAFE:
                    _run_node_template_safe_surge_quota_preflight(
                        source_payload=source_payload,
                        generated_config=generated_config,
                        source_component=source_component,
                        plan=plan,
                        max_surge_count=resolve_strategy_max_surge_count(
                            policy,
                            resolved_max_surge_count,
                        ),
                        request_groups=tuple(
                            group
                            for group in plan.node_groups
                            if group.source is not None and _node_template_request_needed(group)
                        ),
                    )
            if not plan.mutates and not plan.rollout_incomplete and not source_sync_required:
                readiness = verify_mk8s_upgrade_plan_ready(
                    executor=executor,
                    plan=plan,
                    label="MK8s node-template upgrade",
                )
                report_path, _report_json_path = _write_upgrade_node_template_report(
                    paths,
                    plan=plan,
                    readiness=readiness,
                    validations=[],
                )
                console.print(f"[green]{readiness.summary()}[/green]")
                console.print(f"MK8s node-template upgrade report: {report_path}", soft_wrap=True)
                console.print(
                    f"MK8s target {target.selector} is already on Kubernetes "
                    f"{normalized_to_version}, OS {target_os}, and the requested GPU stack."
                )
                return
            if not plan.mutates and not plan.rollout_incomplete and source_sync_required:
                console.print(
                    "Live MK8s resources already match the requested node template; "
                    "reconciling config.yaml and generated Terraform so desired state "
                    "stays authoritative."
                )
            if not plan.mutates and plan.rollout_incomplete:
                console.print(
                    "MK8s node-template changes are already requested on the live resources; "
                    "waiting for the in-progress node-group rollout to finish."
                )

            _run_generated_bundle_validation(
                generated_config,
                paths,
                auto_auth_bootstrap=auto_auth_bootstrap,
                title="Node-template upgrade preflight",
                quota_phase="upgrade",
                flux_command_name="upgrade",
                manifest=manifest,
                prompt_mysterybox_payload_values=False,
            )

            original_strategies = source_node_group_strategy_snapshot(
                source_payload,
                instance_id=target.instance_id,
            )
            temporary_strategy = terraform_node_group_strategy_for_policy(
                policy,
                resolved_timeout,
                max_surge_count=resolved_max_surge_count,
            )
            strategy_restore_after_wait = _upgrade_strategy_restore_after_wait(
                temporary_strategy=temporary_strategy,
                rollout_incomplete=plan.rollout_incomplete,
                source_sync_required=source_sync_required,
            )

            node_group_stage_count = sum(
                1
                for planned_group in plan.node_groups
                if planned_group.source is not None and _node_template_request_needed(planned_group)
            )
            planned_stage_count, extra_stage_summaries = _upgrade_planned_stage_count(
                control_plane_stage_count=len(plan.hops),
                node_group_stage_count=node_group_stage_count,
                source_sync_required=source_sync_required,
                strategy_restore_after_wait=strategy_restore_after_wait,
                temporary_strategy=temporary_strategy,
            )
            if planned_stage_count:
                stage_summaries = [
                    f"{len(plan.hops)} control-plane stage(s)",
                    f"{node_group_stage_count} node-group template stage(s)",
                    *extra_stage_summaries,
                ]
                console.print(
                    "Node-template upgrade execution stages are per control-plane hop and "
                    "per node group, not per node: " + ", ".join(stage_summaries) + ".",
                    soft_wrap=True,
                )
            stage_number = 0
            stage_applied = False
            waited_for_existing_rollout = False

            def _stage_strategy(active_group_key: str | None = None) -> bool:
                if temporary_strategy is None:
                    return False
                strategies = dict(original_strategies)
                if active_group_key:
                    strategies[active_group_key] = temporary_strategy
                return set_source_node_group_strategies(
                    source_payload,
                    instance_id=target.instance_id,
                    strategies=strategies,
                )

            def _render_validate_apply_stage(
                title: str,
            ) -> tuple[Any, ProjectPaths, Mapping[str, Any]]:
                nonlocal stage_applied, stage_number
                stage_number += 1
                stage_label = (
                    f"stage {stage_number}/{planned_stage_count}"
                    if planned_stage_count
                    else f"stage {stage_number}"
                )
                config_path.write_text(
                    render_updated_source_payload(source_payload),
                    encoding="utf-8",
                )
                console.print(f"Updated {config_path} for {stage_label}: {title}.", soft_wrap=True)
                _run_internal_render_command(config_path, force=True)
                staged_config, staged_paths, staged_manifest = _load_deploy_context(config_path)
                mysterybox_payload_env = _run_generated_bundle_validation(
                    staged_config,
                    staged_paths,
                    auto_auth_bootstrap=auto_auth_bootstrap,
                    title=f"Validate rendered {stage_label}: {title}",
                    quota_phase="upgrade",
                    flux_command_name="upgrade",
                    manifest=staged_manifest,
                    prompt_mysterybox_payload_values=False,
                )
                status_watchers = _manifest_status_watchers(
                    staged_manifest
                ) or _enabled_status_watcher_specs(staged_config)
                apply_kwargs: dict[str, Any] = {
                    "initialize": False,
                    "run_mk8s_preflight": False,
                }
                if status_watchers:
                    apply_kwargs["status_watchers"] = status_watchers
                if mysterybox_payload_env:
                    apply_kwargs["extra_env"] = mysterybox_payload_env
                plan_env = _terraform_runtime_env(staged_config)
                if mysterybox_payload_env:
                    plan_env.update(mysterybox_payload_env)
                console.print(f"Planning Terraform {stage_label}: {title}.", soft_wrap=True)
                terraform_plan(staged_paths.infra_dir, extra_env=plan_env, quiet=True)
                console.print(f"Applying Terraform {stage_label}: {title}.", soft_wrap=True)
                _run_terraform_apply_with_status(staged_config, staged_paths, **apply_kwargs)
                stage_applied = True
                return staged_config, staged_paths, staged_manifest

            def _restore_temporary_strategy_files_after_error() -> None:
                if temporary_strategy is None:
                    return
                try:
                    restored = set_source_node_group_strategies(
                        source_payload,
                        instance_id=target.instance_id,
                        strategies=original_strategies,
                    )
                    if restored:
                        config_path.write_text(
                            render_updated_source_payload(source_payload),
                            encoding="utf-8",
                        )
                        _run_internal_render_command(config_path, force=True)
                        console.print(
                            "Restored temporary node-group upgrade strategy in config.yaml "
                            "and generated/ after failed node-template stage."
                        )
                except Exception as cleanup_exc:
                    console.print(
                        "[yellow]Could not restore temporary node-group upgrade strategy "
                        f"after failed node-template stage:[/yellow] {cleanup_exc}"
                    )

            try:
                for hop in plan.hops:
                    update_source_k8s_versions(
                        source_payload,
                        instance_id=target.instance_id,
                        target_version=hop.to_version,
                        node_group_versions=desired_group_versions,
                    )
                    _stage_strategy(None)
                    generated_config, paths, manifest = _render_validate_apply_stage(
                        f"control-plane upgrade to Kubernetes {hop.to_version}"
                    )
                    executor.wait_cluster_version(
                        cluster_id=plan.cluster_id,
                        version=hop.to_version,
                    )

                for planned_group in plan.node_groups:
                    if planned_group.source is None:
                        raise RuntimeError(
                            f"Live node group '{planned_group.name}' is not declared in config.yaml; "
                            "cxcli cannot safely upgrade it through Terraform."
                        )
                    group_key = planned_group.source.key
                    desired_group_versions[group_key] = normalized_to_version
                    target_drivers_preset = node_template_target_drivers_preset(
                        planned_group,
                        target_gpu_stack_preset=target_gpu_stack_preset,
                    )
                    if node_group_node_template_rollout_complete(
                        planned_group.raw,
                        version=normalized_to_version,
                        os=target_os,
                        drivers_preset=target_drivers_preset,
                    ):
                        continue
                    if not _node_template_request_needed(planned_group):
                        wait_for_node_template_rollout(
                            executor=executor,
                            plan=plan,
                            planned_group=planned_group,
                        )
                        waited_for_existing_rollout = True
                        continue
                    update_source_node_template(
                        source_payload,
                        instance_id=target.instance_id,
                        target_version=normalized_to_version,
                        target_os=target_os,
                        target_gpu_stack_preset=target_gpu_stack_preset,
                        node_group_keys=(group_key,),
                        node_group_versions=desired_group_versions,
                    )
                    _stage_strategy(group_key)
                    generated_config, paths, manifest = _render_validate_apply_stage(
                        f"node-group {planned_group.name} node-template upgrade to "
                        f"Kubernetes {normalized_to_version}, OS {target_os}"
                    )
                    wait_for_node_template_rollout(
                        executor=executor,
                        plan=plan,
                        planned_group=planned_group,
                    )

                final_changed = update_source_node_template(
                    source_payload,
                    instance_id=target.instance_id,
                    target_version=normalized_to_version,
                    target_os=target_os,
                    target_gpu_stack_preset=target_gpu_stack_preset,
                    node_group_keys=selected_group_keys,
                    node_group_versions=final_group_versions,
                )
                strategy_restored = _stage_strategy(None)
                strategy_restore_required = _upgrade_strategy_restore_required(
                    strategy_restore_after_wait=strategy_restore_after_wait,
                    waited_for_existing_rollout=waited_for_existing_rollout,
                    stage_applied=stage_applied,
                )
                if (
                    final_changed
                    or strategy_restored
                    or strategy_restore_required
                    or (source_sync_required and not stage_applied)
                ):
                    stage_title = _upgrade_final_stage_title(
                        strategy_restored=strategy_restored,
                        strategy_restore_required=strategy_restore_required,
                        source_sync_title="source node-template sync",
                    )
                    generated_config, paths, manifest = _render_validate_apply_stage(stage_title)
            except Exception:
                _restore_temporary_strategy_files_after_error()
                raise

            validations = _filter_validations_for_target(
                _manifest_deploy_validations(manifest),
                target_ref=target.instance_id,
            )
            skip_kinds = _resolve_deploy_validation_skip_kinds(tuple(skip_validation or ()))
            validations = _filter_deploy_validations(
                validations,
                skip_validations=skip_validations,
                skip_kinds=skip_kinds,
            )
            if validations:
                _run_deploy_validations(
                    validations,
                    reports_dir=paths.reports_dir,
                    extra_env=kube_env,
                    emit=lambda message: console.print(message, highlight=False),
                )
            readiness = verify_mk8s_upgrade_plan_ready(
                executor=executor,
                plan=plan,
                label="MK8s node-template upgrade",
            )
            report_path, _report_json_path = _write_upgrade_node_template_report(
                paths,
                plan=plan,
                readiness=readiness,
                validations=validations,
            )
            console.print(f"[green]{readiness.summary()}[/green]")
            console.print(f"MK8s node-template upgrade report: {report_path}", soft_wrap=True)
            console.print(
                f"[green]MK8s node-template upgrade completed[/green]: "
                f"{target.selector} -> Kubernetes {normalized_to_version}, OS {target_os}"
            )
    except typer.Exit:
        raise
    except Exception as exc:  # pragma: no cover - CLI surface
        _exit_with_error(exc)
    finally:
        _DEPLOY_VALIDATION_WARNING_CACHE.reset(warning_cache_token)
        if sdk is not None:
            with suppress(Exception):
                sdk.sync_close()


@upgrade_app.command(
    "node-group",
    short_help="Plan an MK8s node-group hardware, preset, or fabric migration.",
    epilog=(
        "Example: nebius-cxcli upgrade node-group <config.yaml> infra:mk8s@<target> "
        "--node-group worker --to-platform gpu-b200-sxm --to-preset 8gpu-160vcpu-1792gb "
        "--to-fabric fabric-6 --dry-run. Omit --to-fabric for a GPU-cluster node group "
        "to keep its current fabric. Use upgrade node-template instead for Kubernetes "
        "version, OS, or Nebius-image GPU stack rolling updates that do not change "
        "hardware platform, hardware preset, CPU/GPU kind, GPU cluster, or fabric. "
        "Current --execute --approve writes "
        "generated/reports/upgrade-node-group-report.md and "
        "generated/reports/upgrade-node-group-report.json at the approved "
        "pre-mutation gate."
    ),
)
def upgrade_node_group_command(
    config_path: Annotated[
        Path,
        typer.Argument(metavar="CONFIG_YAML", help=_CONFIG_YAML_ARGUMENT_HELP),
    ],
    target_selector: Annotated[
        str,
        typer.Argument(
            metavar="TARGET",
            help="Target selector, for example infra:mk8s@mk8s.",
        ),
    ],
    node_group: Annotated[
        str,
        typer.Option(
            "--node-group",
            help="Concrete MK8s node-group key to migrate.",
        ),
    ],
    to_platform: Annotated[
        str,
        typer.Option(
            "--to-platform",
            help="Target Compute platform for the replacement node group.",
        ),
    ] = "",
    to_preset: Annotated[
        str,
        typer.Option(
            "--to-preset",
            help="Target hardware preset for the replacement node group.",
        ),
    ] = "",
    to_os: Annotated[
        str,
        typer.Option(
            "--to-os",
            help="Target OS image for the replacement node group.",
        ),
    ] = "",
    to_gpu_stack_preset: Annotated[
        str,
        typer.Option(
            "--to-gpu-stack-preset",
            help=(
                "Target Nebius-image GPU stack preset when hardware migration should also "
                "change the replacement GPU node image."
            ),
        ),
    ] = "",
    to_fabric: Annotated[
        str,
        typer.Option(
            "--to-fabric",
            help=(
                "Optional target InfiniBand fabric. Omit for GPU-cluster node groups to "
                "keep the current fabric; CPU and non-InfiniBand GPU groups reject it."
            ),
        ),
    ] = "",
    dry_run: Annotated[
        bool,
        typer.Option(
            "--dry-run/--execute",
            help=(
                "Use --dry-run for the read-only migration plan. Use --execute --approve only "
                "after accepting that plan; current execute writes an approved pre-mutation "
                "checkpoint and stops before live replacement/cutover/retirement."
            ),
        ),
    ] = True,
    approve: Annotated[
        bool,
        typer.Option(
            "--approve/--no-approve",
            help="Required with --execute before the approved pre-mutation checkpoint is written.",
        ),
    ] = False,
) -> None:
    """Plan an explicit Terraform-managed node-group migration."""

    try:
        if not _non_empty_text(node_group):
            raise RuntimeError("--node-group is required for upgrade node-group.")
        source_payload = _load_source_payload(config_path)
        generated_config, paths, manifest = _load_deploy_context_readonly(config_path)
        plan = _plan_node_group_migration(
            source_payload=source_payload,
            generated_config=generated_config,
            paths=paths,
            manifest=manifest,
            target_selector=target_selector,
            node_group=node_group,
            to_platform=to_platform,
            to_preset=to_preset,
            to_os=to_os,
            to_gpu_stack_preset=to_gpu_stack_preset,
            to_fabric=to_fabric,
        )
        _print_upgrade_plan_lines(
            _format_node_group_migration_plan(
                plan,
                config_path=config_path,
                dry_run=dry_run,
            )
        )
        if dry_run:
            return
        if not approve:
            raise RuntimeError("upgrade node-group --execute requires --approve.")
        if _node_group_migration_quota_blocks(plan):
            raise RuntimeError(
                "upgrade node-group --execute requires clean target quota/capacity preflight "
                "before checkpoint or mutation."
            )
        if plan.soperator_managed and plan.node_group_kind == "gpu" and not plan.sfs_evidence:
            raise RuntimeError(
                "upgrade node-group --execute requires SFS/PVC-backed Soperator worker data "
                "evidence before mutation. Local node disks and emptyDir are not preserved."
            )
        checkpoint_path = _node_group_migration_checkpoint_path(
            paths,
            instance_id=plan.instance_id,
            node_group=plan.node_group,
        )
        checkpoint_path.parent.mkdir(parents=True, exist_ok=True)
        checkpoint_path.write_text(
            json.dumps(
                {
                    "phase": "approved-pre-mutation",
                    "target": plan.target_selector,
                    "node_group": plan.node_group,
                    "node_group_kind": plan.node_group_kind,
                    "gpu_cluster_key": plan.gpu_cluster_key,
                    "from_platform": plan.current_platform,
                    "to_platform": plan.target_platform,
                    "from_preset": plan.current_preset,
                    "to_preset": plan.target_preset,
                    "from_fabric": plan.current_config_fabric,
                    "to_fabric": plan.effective_target_fabric,
                    "approved": True,
                    "updated_at": datetime.now(UTC).isoformat(),
                },
                indent=2,
                sort_keys=True,
            )
            + "\n",
            encoding="utf-8",
        )
        report_path, _report_json_path = _write_upgrade_node_group_report(
            paths,
            plan=plan,
            checkpoint_path=checkpoint_path,
            status="approved-pre-mutation",
        )
        raise RuntimeError(
            "upgrade node-group --execute reached the approved pre-mutation gate and wrote "
            f"{checkpoint_path}. Node-group upgrade report: {report_path}. "
            "The live replacement/cutover/retirement executor is not enabled yet, so cxcli "
            "stopped before making changes."
        )
    except typer.Exit:
        raise
    except Exception as exc:  # pragma: no cover - CLI surface
        _exit_with_error(exc)


