def _component_source_validation_failure_message(
    source_path: Path,
    source_issues: Sequence[str],
    *,
    include_skip_guidance: bool = False,
    selected_app_ids: set[str] | None = None,
    include_infra: bool = True,
) -> str:
    if selected_app_ids is None:
        scope_text = "the full component catalog, including optional app charts"
    elif selected_app_ids:
        app_list = ", ".join(sorted(selected_app_ids))
        infra_text = "all infra sources and " if include_infra else ""
        scope_text = f"{infra_text}the selected app chart source(s): {app_list}"
    else:
        scope_text = "all infra component sources"
    message = (
        f"Component catalog/settings validation failed for {source_path}:\n  - "
        + "\n  - ".join(source_issues)
        + f"\n\nThis validation checks {scope_text}. "
        "If the failure is a transient Helm repository, OCI registry, or network timeout, "
        "retry or increase NEBIUS_CXCLI_HELM_TIMEOUT_SECONDS."
    )
    if include_skip_guidance:
        message += (
            " During create/component add, rerun with --no-validate-sources "
            "to skip this source check."
        )
    return message


def _validate_component_sources_or_raise(
    *,
    selected_app_ids: set[str] | None = None,
    include_infra: bool = True,
) -> None:
    with console.status("[cyan]Validating component catalog/settings...[/cyan]"):
        registry_kwargs: dict[str, Any] = {}
        if selected_app_ids is not None:
            registry_kwargs["selected_app_ids"] = selected_app_ids
        if not include_infra:
            registry_kwargs["include_infra"] = include_infra
        source_path, source_issues, source_warnings = _validate_component_sources_registry(
            **registry_kwargs,
        )
    for warning in source_warnings:
        console.print(f"{warning_markup('Source validation warning:')} {warning}")
    if source_issues:
        raise RuntimeError(
            _component_source_validation_failure_message(
                source_path,
                source_issues,
                include_skip_guidance=True,
                selected_app_ids=selected_app_ids,
                include_infra=include_infra,
            )
        )


def _validate_final_enabled_app_sources_or_raise(
    *,
    payload: dict[str, Any],
    app_entries: tuple[ComponentEntry, ...],
    already_validated_app_ids: set[str],
    candidate_app_ids: set[str] | None = None,
) -> set[str]:
    enabled_app_ids = _enabled_ids_from_runtime_payload(
        payload=payload,
        entries=app_entries,
    )
    app_ids_to_validate = set(enabled_app_ids)
    if candidate_app_ids is not None:
        app_ids_to_validate &= candidate_app_ids
    app_ids_to_validate -= already_validated_app_ids
    if app_ids_to_validate:
        _validate_component_sources_or_raise(
            selected_app_ids=app_ids_to_validate,
            include_infra=False,
        )
    return enabled_app_ids


def _identity_values_from_payload(
    payload: Mapping[str, Any],
) -> tuple[str, str, str, str, str | None]:
    client_info = payload.get("client_info")
    if not isinstance(client_info, Mapping):
        raise RuntimeError("config.yaml is missing client_info")
    nebius = client_info.get("nebius")
    if not isinstance(nebius, Mapping):
        raise RuntimeError("config.yaml is missing client_info.nebius")
    notifications = client_info.get("notifications")
    if not isinstance(notifications, Mapping):
        raise RuntimeError("config.yaml is missing client_info.notifications")
    return (
        _non_empty_text(client_info.get("client_name")),
        _non_empty_text(nebius.get("tenant_id")),
        _non_empty_text(nebius.get("project_id")),
        _non_empty_text(nebius.get("region_id")),
        str(notifications.get("email")).strip() if notifications.get("email") is not None else None,
    )


def _dependency_seed_payload(
    *,
    client_name: str,
    tenant_id: str,
    project_id: str,
    region_id: str,
    email: str | None,
    selected_infra: set[str],
    selected_apps: set[str],
    infra_entries: tuple[ComponentEntry, ...],
    app_entries: tuple[ComponentEntry, ...],
    existing_payload: dict[str, Any] | None,
    merge_existing: bool,
    app_version_overrides: dict[str, str] | None = None,
) -> dict[str, Any] | None:
    if not selected_apps:
        return None
    dependency_seed_yaml = starter_config_yaml(
        client_name=client_name,
        tenant_id=tenant_id,
        project_id=project_id,
        region_id=region_id,
        email=email,
        selected_infra=selected_infra,
        selected_apps=selected_apps,
        infra_entries=infra_entries,
        app_entries=app_entries,
    )
    parsed_seed_payload = yaml.safe_load(dependency_seed_yaml) or {}
    if not isinstance(parsed_seed_payload, dict):
        return None
    if merge_existing and existing_payload is not None:
        parsed_seed_payload = _deep_merge_payload(parsed_seed_payload, existing_payload)
        parsed_seed_payload = _filter_runtime_payload_for_selected_components(
            payload=parsed_seed_payload,
            selected_infra=selected_infra,
            selected_apps=selected_apps,
            infra_entries=infra_entries,
            app_entries=app_entries,
        )
    materialize_shared_defaults(
        payload=parsed_seed_payload,
        infra_entries=infra_entries,
        app_entries=app_entries,
    )
    _apply_app_release_overrides(
        payload=parsed_seed_payload,
        selected_apps=selected_apps,
        namespace_overrides={},
        release_name_overrides={},
        version_overrides=app_version_overrides or {},
    )
    return parsed_seed_payload


def _starter_component_payload(
    *,
    client_name: str,
    tenant_id: str,
    project_id: str,
    region_id: str,
    email: str | None,
    selected_infra: set[str],
    selected_apps: set[str],
    infra_entries: tuple[ComponentEntry, ...],
    app_entries: tuple[ComponentEntry, ...],
    app_namespace_overrides: dict[str, str] | None = None,
    app_releasename_overrides: dict[str, str] | None = None,
    app_version_overrides: dict[str, str] | None = None,
) -> dict[str, Any]:
    starter_yaml = starter_config_yaml(
        client_name=client_name,
        tenant_id=tenant_id,
        project_id=project_id,
        region_id=region_id,
        email=email,
        selected_infra=selected_infra,
        selected_apps=selected_apps,
        infra_entries=infra_entries,
        app_entries=app_entries,
    )
    starter_payload = yaml.safe_load(starter_yaml) or {}
    if not isinstance(starter_payload, dict):
        raise RuntimeError("Generated starter config payload must be a mapping")
    starter_payload = _filter_runtime_payload_for_selected_components(
        payload=starter_payload,
        selected_infra=selected_infra,
        selected_apps=selected_apps,
        infra_entries=infra_entries,
        app_entries=app_entries,
    )
    _apply_app_release_overrides(
        payload=starter_payload,
        selected_apps=selected_apps,
        namespace_overrides=app_namespace_overrides or {},
        release_name_overrides=app_releasename_overrides or {},
        version_overrides=app_version_overrides or {},
    )
    materialize_shared_defaults(
        payload=starter_payload,
        infra_entries=infra_entries,
        app_entries=app_entries,
    )
    _seed_infra_project_scope_defaults(
        payload=starter_payload,
        infra_entries=infra_entries,
    )
    _seed_infra_shared_admin_ssh_public_key(
        payload=starter_payload,
        infra_entries=infra_entries,
    )
    normalize_runtime_config_payload(starter_payload)
    return starter_payload


def _ensure_payload_contains_component_rows(
    *,
    payload: dict[str, Any],
    seed_payload: dict[str, Any],
) -> None:
    scopes = (
        ("infra", "components"),
        ("apps", "charts"),
    )
    for scope_name, collection_name in scopes:
        section = payload.get(scope_name)
        if not isinstance(section, dict):
            section = {}
            payload[scope_name] = section
        seed_section = seed_payload.get(scope_name)
        if not isinstance(seed_section, dict):
            continue
        rows = section.get(collection_name)
        if not isinstance(rows, list):
            rows = []
            section[collection_name] = rows
        seed_rows = seed_section.get(collection_name)
        if not isinstance(seed_rows, list):
            continue
        existing_keys = {
            (component_type_id(item), component_instance_id(item))
            for item in rows
            if isinstance(item, dict)
        }
        for item in seed_rows:
            if not isinstance(item, dict):
                continue
            dedupe_key = (component_type_id(item), component_instance_id(item))
            if dedupe_key in existing_keys:
                continue
            rows.append(copy.deepcopy(item))
            existing_keys.add(dedupe_key)


def _component_selector_scope_label(scope: ComponentScope) -> str:
    return "INFRA" if scope == "infra" else "APPS"


def _prompt_component_scope_selection(
    *,
    action: str,
    scope: ComponentScope,
    entries: tuple[ComponentEntry, ...],
) -> set[str]:
    if not entries:
        console.print(
            f"{_component_selector_scope_label(scope)} components available to {action}: (none)"
        )
        return set()
    selected = _prompt_component_with_checkboxes(
        scope=scope,
        entries=entries,
        defaults=set(),
    )
    selected_ids = {token for token in selected if token}
    _print_component_scope_selection_summary(
        scope=scope,
        selected=selected_ids,
        entries=entries,
    )
    return selected_ids


def _prompt_component_instance_selection(
    *,
    action: str,
    scope: ComponentScope,
    specs: tuple[tuple[ComponentEntry, dict[str, Any]], ...],
) -> set[str]:
    if not specs:
        console.print(
            f"{_component_selector_scope_label(scope)} component instances available to {action}: (none)"
        )
        return set()

    if _is_tty_session():
        try:
            import questionary
        except Exception as exc:
            install_hint = f"{sys.executable} -m pip install questionary"
            console.print(
                f"{warning_markup('Interactive checkbox UI unavailable:')} "
                f"{exc}. Falling back to text prompt. "
                f"Install it with: {install_hint}"
            )
        else:
            _configure_questionary_checkbox_symbols()
            selected = questionary.checkbox(
                f"Select {scope} component instances",
                choices=[
                    questionary.Choice(
                        title=(
                            f"{_component_instance_selector_label(entry, instance_id=str(row['instance_id']))}"
                            f"  ({entry.description})"
                        ),
                        value=str(row["instance_id"]),
                        checked=False,
                    )
                    for entry, row in specs
                ],
                instruction="Use arrows and space to toggle; press Enter to confirm.",
                qmark="",
            ).ask()
            if selected is None:
                raise typer.Abort()
            return {str(item).strip().lower() for item in selected if str(item).strip()}

    console.print(f"\n{scope.upper()} component instances:")
    for index, (entry, row) in enumerate(specs, start=1):
        instance_id = str(row["instance_id"])
        label = _component_instance_selector_label(entry, instance_id=instance_id)
        console.print(f"  [ ] [{index}] {label:<36} {entry.description}")
    raw = typer.prompt(
        f"Select {scope} component instances to {action} (comma-separated ids or indexes)",
        default="",
    ).strip()
    tokens = _split_multi_value_tokens([raw])
    if not tokens:
        return set()
    selected: set[str] = set()
    by_index = {
        str(index): str(row["instance_id"]) for index, (_entry, row) in enumerate(specs, start=1)
    }
    by_instance = {str(row["instance_id"]): str(row["instance_id"]) for _entry, row in specs}
    for token in tokens:
        if token in by_index:
            selected.add(by_index[token])
            continue
        normalized = normalize_component_token(token)
        if normalized in by_instance:
            selected.add(by_instance[normalized])
            continue
        raise RuntimeError(
            f"Unknown {scope} component instance '{token}'. Choose a listed instance id or index."
        )
    return selected


@dataclass(frozen=True)
class _ComponentAddTarget:
    scope: ComponentScope
    component_id: str
    requested_instance_id: str | None = None
    allocate_new_infra_instance_if_enabled: bool = False


@dataclass(frozen=True)
class _ComponentRemoveTarget:
    scope: ComponentScope
    component_id: str
    instance_id: str


def _parse_scoped_component_selector(token: str) -> tuple[ComponentScope | None, str]:
    normalized = token.strip().lower()
    if ":" not in normalized:
        return None, normalized
    scope_raw, body = normalized.split(":", maxsplit=1)
    scope = cast(ComponentScope, scope_raw)
    if scope not in {"infra", "apps"}:
        raise RuntimeError(
            f"Invalid component selector '{token}'. Use '<component-id>' or "
            "scoped 'infra:<id>' / 'apps:<id>' (plural apps:, not app:)."
        )
    return scope, body.strip()


def _resolve_component_add_targets(
    *,
    tokens: list[str],
    infra_entries: tuple[ComponentEntry, ...],
    app_entries: tuple[ComponentEntry, ...],
) -> list[_ComponentAddTarget]:
    infra_lookup = {entry.id: entry for entry in infra_entries}
    app_lookup = {entry.id: entry for entry in app_entries}
    lookup = {**infra_lookup, **app_lookup}

    normalized = [token.strip() for token in tokens if token.strip()]
    if len(normalized) == 1:
        keyword = normalized[0].lower()
        if keyword == "none":
            return []
        if keyword == "all":
            return [
                *(
                    _ComponentAddTarget(scope="infra", component_id=entry.id)
                    for entry in infra_entries
                ),
                *(
                    _ComponentAddTarget(scope="apps", component_id=entry.id)
                    for entry in app_entries
                ),
            ]

    targets: list[_ComponentAddTarget] = []
    for token in normalized:
        scope, body = _parse_scoped_component_selector(token)
        component_raw, separator, instance_raw = body.partition("@")
        component_id = normalize_component_token(component_raw)
        if not component_id:
            raise RuntimeError(f"Invalid component selector '{token}'. Component id is required.")
        entry = lookup.get(component_id)
        if entry is None:
            available = ", ".join(sorted(lookup))
            raise RuntimeError(f"Unknown component id '{component_id}'. Available ids: {available}")
        if scope is not None and entry.scope != scope:
            raise RuntimeError(
                f"Component selector '{token}' targets scope '{scope}', but '{component_id}' is declared under '{entry.scope}'."
            )
        requested_instance_id = normalize_component_token(instance_raw) if separator else ""
        if requested_instance_id and not INSTANCE_ID_PATTERN.fullmatch(requested_instance_id):
            raise RuntimeError(
                f"Invalid resource name or target id '{instance_raw}'. "
                "Expected lowercase letters, digits, and hyphens."
            )
        targets.append(
            _ComponentAddTarget(
                scope=entry.scope,
                component_id=component_id,
                requested_instance_id=requested_instance_id or None,
                allocate_new_infra_instance_if_enabled=(
                    entry.scope == "infra" and not requested_instance_id
                ),
            )
        )
    return targets


def _resolve_component_remove_targets(
    *,
    tokens: list[str],
    payload: dict[str, Any],
    infra_entries: tuple[ComponentEntry, ...],
    app_entries: tuple[ComponentEntry, ...],
) -> tuple[list[_ComponentRemoveTarget], tuple[str, ...]]:
    enabled_specs = [
        *_enabled_component_instance_specs(payload, scope="infra", entries=infra_entries),
        *_enabled_component_instance_specs(payload, scope="apps", entries=app_entries),
    ]
    by_instance: dict[str, list[_ComponentRemoveTarget]] = {}
    by_scope_and_type: dict[tuple[ComponentScope, str], list[_ComponentRemoveTarget]] = {}
    for entry, row in enabled_specs:
        instance_id = str(row["instance_id"])
        target = _ComponentRemoveTarget(
            scope=entry.scope,
            component_id=entry.id,
            instance_id=instance_id,
        )
        by_instance.setdefault(instance_id, []).append(target)
        by_scope_and_type.setdefault((entry.scope, entry.id), []).append(target)

    normalized = [token.strip() for token in tokens if token.strip()]
    if len(normalized) == 1:
        keyword = normalized[0].lower()
        if keyword == "none":
            return [], ()
        if keyword == "all":
            return [item for items in by_instance.values() for item in items], ()

    skipped: list[str] = []
    selected: list[_ComponentRemoveTarget] = []
    seen_instances: set[str] = set()
    for token in normalized:
        scope, body = _parse_scoped_component_selector(token)
        component_raw, separator, instance_raw = body.partition("@")
        if separator:
            component_id = normalize_component_token(component_raw)
            instance_id = normalize_component_token(instance_raw)
            if not component_id or not instance_id:
                raise RuntimeError(
                    f"Invalid component selector '{token}'. Use '<row-id>' or "
                    "'<component-id>@<resource-name-or-target-id>'."
                )
            candidates = by_instance.get(instance_id, [])
            candidate = next(
                (
                    item
                    for item in candidates
                    if item.component_id == component_id and (scope is None or item.scope == scope)
                ),
                None,
            )
            if candidate is None:
                skipped.append(token)
                continue
            selected_key = f"{candidate.scope}:{candidate.component_id}@{candidate.instance_id}"
            if selected_key not in seen_instances:
                seen_instances.add(selected_key)
                selected.append(candidate)
            continue

        normalized_token = normalize_component_token(body)
        if not normalized_token:
            raise RuntimeError(f"Invalid component selector '{token}'.")
        candidate_lists = [
            specs
            for (candidate_scope, candidate_component_id), specs in by_scope_and_type.items()
            if candidate_component_id == normalized_token
            and (scope is None or candidate_scope == scope)
        ]
        flattened = [item for specs in candidate_lists for item in specs]
        if len(flattened) > 1:
            available = ", ".join(sorted(item.instance_id for item in flattened))
            raise RuntimeError(
                f"Component selector '{token}' matches multiple enabled instances. "
                "Use an exact resource name, target id, row id, or "
                f"'<component-id>@<resource-name-or-target-id>'. Available rows: {available}"
            )
        if len(flattened) == 1:
            only = flattened[0]
            selected_key = f"{only.scope}:{only.component_id}@{only.instance_id}"
            if selected_key not in seen_instances:
                seen_instances.add(selected_key)
                selected.append(only)
            continue

        instance_matches = [
            item
            for item in by_instance.get(normalized_token, [])
            if scope is None or item.scope == scope
        ]
        if len(instance_matches) > 1:
            available = ", ".join(
                sorted(f"{item.component_id}@{item.instance_id}" for item in instance_matches)
            )
            raise RuntimeError(
                f"Component selector '{token}' matches multiple enabled instances. "
                "Use '<component-id>@<resource-name-or-target-id>'. "
                f"Available rows: {available}"
            )
        if len(instance_matches) == 1:
            candidate = instance_matches[0]
            selected_key = f"{candidate.scope}:{candidate.component_id}@{candidate.instance_id}"
            if selected_key not in seen_instances:
                seen_instances.add(selected_key)
                selected.append(candidate)
            continue
        skipped.append(token)
    return selected, tuple(sorted(set(skipped)))


def _runtime_required_input_leaf_names(entry: ComponentEntry) -> set[str]:
    if entry.scope != "infra" or not entry.source:
        return set()
    try:
        return set(runtime_introspection.module_required_variables(entry.source))
    except Exception:
        return set()


def _parse_component_value_overrides(
    *,
    raw_values: list[str] | None,
    option_name: str,
) -> dict[str, str]:
    overrides: dict[str, str] = {}
    for token in _split_multi_value_tokens(raw_values):
        if "=" not in token:
            raise RuntimeError(
                f"Invalid {option_name} value '{token}'. Expected '<component-id>=<value>'."
            )
        component_raw, value_raw = token.split("=", maxsplit=1)
        component_id = component_raw.strip().lower()
        value = value_raw.strip()
        if not component_id or not COMPONENT_ID_PATTERN.fullmatch(component_id):
            raise RuntimeError(
                f"Invalid {option_name} component id '{component_raw}'. "
                "Expected lowercase letters, digits, and hyphens."
            )
        if not value:
            raise RuntimeError(
                f"Invalid {option_name} value for '{component_id}'. Value cannot be empty."
            )
        if component_id in overrides:
            raise RuntimeError(f"Duplicate {option_name} override for component '{component_id}'.")
        overrides[component_id] = value
    return overrides


_SUBNET_ATTACHED_INFRA_COMPONENT_IDS = frozenset(
    {"mk8s", "vm", "nfs", "wireguard-gw", "ssh-jumphost"}
)
_NETWORK_ONLY_INFRA_COMPONENT_IDS = frozenset({"managed-postgresql"})
_NETWORK_ATTACHED_INFRA_COMPONENT_IDS = (
    _SUBNET_ATTACHED_INFRA_COMPONENT_IDS | _NETWORK_ONLY_INFRA_COMPONENT_IDS
)
_PLANNED_BINDING_TOKEN_PREFIX = "planned:"


def _parse_vpc_id_overrides(
    *,
    raw_values: list[str] | None,
    option_name: str,
) -> tuple[tuple[str, ...], dict[tuple[str, str | None], str]]:
    bare_values: list[str] = []
    scoped_values: dict[tuple[str, str | None], str] = {}
    for token in _split_multi_value_tokens(raw_values):
        if "=" not in token:
            value = token.strip()
            if not value:
                raise RuntimeError(f"Invalid {option_name} value. Value cannot be empty.")
            bare_values.append(value)
            continue

        selector_raw, value_raw = token.split("=", maxsplit=1)
        selector = selector_raw.strip()
        value = value_raw.strip()
        if not selector or not value:
            raise RuntimeError(
                f"Invalid {option_name} value '{token}'. Expected '<infra-component-selector>=<id>'."
            )
        scope, body = _parse_scoped_component_selector(selector)
        if scope not in {None, "infra"}:
            raise RuntimeError(
                f"Invalid {option_name} selector '{selector}'. VPC overrides apply only to infra components."
            )
        component_raw, separator, instance_raw = body.partition("@")
        component_id = normalize_component_token(component_raw)
        instance_id = normalize_component_token(instance_raw) if separator else ""
        if not component_id:
            raise RuntimeError(
                f"Invalid {option_name} selector '{selector}'. Component id is required."
            )
        if instance_id and not INSTANCE_ID_PATTERN.fullmatch(instance_id):
            raise RuntimeError(
                f"Invalid {option_name} selector '{selector}'. Instance id must use lowercase letters, digits, and hyphens."
            )
        key = (component_id, instance_id or None)
        if key in scoped_values:
            raise RuntimeError(f"Duplicate {option_name} override for selector '{selector}'.")
        scoped_values[key] = value

    if len(bare_values) > 1:
        raise RuntimeError(f"Specify {option_name} at most once without a component selector.")
    if bare_values and scoped_values:
        raise RuntimeError(f"Do not mix bare and scoped {option_name} values in one command.")
    return tuple(bare_values), scoped_values


@dataclass(frozen=True)
class _PlannedBindingRef:
    source_instance: str
    source_output: str
    key: str | None = None
    attribute: str | None = None


def _parse_planned_vpc_ref(value: str, *, option_name: str, field_name: str) -> _PlannedBindingRef:
    token = value.strip()
    if token.startswith(_PLANNED_BINDING_TOKEN_PREFIX):
        token = token[len(_PLANNED_BINDING_TOKEN_PREFIX) :]
    component_selector, separator, output_selector = token.partition(".")
    component_raw, instance_separator, instance_raw = component_selector.partition("@")
    component_id = normalize_component_token(component_raw)
    instance_id = normalize_component_token(instance_raw) if instance_separator else ""
    if component_id != "vpc" or not instance_separator or not instance_id:
        raise RuntimeError(
            f"Invalid {option_name} value '{value}'. Expected 'vpc@<vpc-instance>.<output>'."
        )
    if not INSTANCE_ID_PATTERN.fullmatch(instance_id):
        raise RuntimeError(
            f"Invalid {option_name} value '{value}'. VPC instance id must use lowercase letters, digits, and hyphens."
        )
    output_parts = [part.strip() for part in output_selector.split(".") if part.strip()]
    if not separator or not output_parts:
        raise RuntimeError(
            f"Invalid {option_name} value '{value}'. Expected 'vpc@<vpc-instance>.<output>'."
        )
    output_name = output_parts[0].replace("-", "_").lower()
    if field_name == "network_id":
        if output_name != "network_id" or len(output_parts) != 1:
            raise RuntimeError(
                f"Invalid {option_name} value '{value}'. Network refs must use "
                "'vpc@<vpc-instance>.network_id'."
            )
        return _PlannedBindingRef(source_instance=instance_id, source_output="network_id")
    if output_name != "subnets" or len(output_parts) != 3:
        raise RuntimeError(
            f"Invalid {option_name} value '{value}'. Subnet refs must use "
            "'vpc@<vpc-instance>.subnets.<subnet-key>.id'."
        )
    subnet_key = output_parts[1]
    attribute = output_parts[2].replace("-", "_")
    if not subnet_key or not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", attribute):
        raise RuntimeError(
            f"Invalid {option_name} value '{value}'. Subnet key and attribute must be non-empty."
        )
    if attribute != "id":
        raise RuntimeError(
            f"Invalid {option_name} value '{value}'. Subnet refs for subnet_id must end in '.id'."
        )
    return _PlannedBindingRef(
        source_instance=instance_id,
        source_output="subnets",
        key=subnet_key,
        attribute=attribute,
    )


def _selected_infra_rows_for_vpc_override(
    *,
    payload: dict[str, Any],
    selected_infra: set[str],
    component_ids: frozenset[str],
) -> list[dict[str, Any]]:
    selected_tokens = {
        normalize_component_token(item)
        for item in selected_infra
        if normalize_component_token(item)
    }
    rows: list[dict[str, Any]] = []
    for row in _dynamic_enabled_infra_component_rows(payload):
        component_id = component_type_id(row)
        instance_id = component_instance_id(row)
        if component_id not in component_ids or not instance_id:
            continue
        if (
            selected_tokens
            and instance_id not in selected_tokens
            and component_id not in selected_tokens
        ):
            continue
        rows.append(row)
    return rows


def _vpc_override_selector_example(component_id: str = "vm", instance_id: str = "worker") -> str:
    return f"infra:{component_id}@{instance_id}=<id>"


def _resolve_vpc_override_target(
    *,
    rows: Sequence[dict[str, Any]],
    selector: tuple[str, str | None],
    option_name: str,
) -> dict[str, Any]:
    component_id, instance_id = selector
    matches = [
        row
        for row in rows
        if component_type_id(row) == component_id
        and (instance_id is None or component_instance_id(row) == instance_id)
    ]
    if len(matches) == 1:
        return matches[0]
    if len(matches) > 1:
        available = ", ".join(
            sorted(
                component_instance_label(component_type_id(row), component_instance_id(row))
                for row in matches
            )
        )
        raise RuntimeError(
            f"{option_name} selector 'infra:{component_id}' matches multiple enabled infra rows. "
            f"Use '<component-id>@<resource-name>'. Available rows: {available}"
        )
    selector_label = (
        component_instance_label(component_id, instance_id)
        if instance_id
        else f"infra:{component_id}"
    )
    applicable = ", ".join(
        sorted(
            component_instance_label(component_type_id(row), component_instance_id(row))
            for row in rows
        )
    )
    raise RuntimeError(
        f"{option_name} selector '{selector_label}' does not match a selected applicable infra component."
        + (f" Applicable rows: {applicable}" if applicable else "")
    )


def _vpc_field_path(
    *,
    payload: dict[str, Any],
    row: Mapping[str, Any],
    field_name: str,
) -> PayloadPath:
    component_id = component_type_id(row)
    instance_id = component_instance_id(row)
    component_path = _dynamic_infra_component_path(
        payload,
        component_id,
        instance_id=instance_id,
    )
    if component_path is None:
        raise RuntimeError(
            f"Could not locate infra component '{component_instance_label(component_id, instance_id)}' in config payload."
        )
    if component_id == "mk8s":
        return component_path + ("inputs", "cluster", field_name)
    return component_path + ("inputs", field_name)


def _vpc_binding_target_path(row: Mapping[str, Any], field_name: str) -> str:
    if component_type_id(row) == "mk8s":
        return f"inputs.cluster.{field_name}"
    return f"inputs.{field_name}"


def _vpc_field_has_binding(
    *,
    payload: dict[str, Any],
    row: Mapping[str, Any],
    field_name: str,
) -> bool:
    component_id = component_type_id(row)
    instance_id = component_instance_id(row)
    component_path = _dynamic_infra_component_path(
        payload,
        component_id,
        instance_id=instance_id,
    )
    if component_path is None:
        return False
    component_node = _get_payload_value(payload, component_path)
    if not isinstance(component_node, Mapping):
        return False
    bindings = component_node.get("bindings")
    return isinstance(bindings, Mapping) and _vpc_binding_target_path(row, field_name) in bindings


def _set_vpc_field(
    *,
    payload: dict[str, Any],
    row: Mapping[str, Any],
    field_name: str,
    value: str,
) -> None:
    if _vpc_field_has_binding(payload=payload, row=row, field_name=field_name):
        raise RuntimeError(
            f"{_format_payload_path(_vpc_field_path(payload=payload, row=row, field_name=field_name))} "
            "cannot use a literal ID because a planned ref binding is already set."
        )
    _set_payload_value_creating_containers(
        payload,
        _vpc_field_path(payload=payload, row=row, field_name=field_name),
        value,
    )


def _set_vpc_binding(
    *,
    payload: dict[str, Any],
    row: Mapping[str, Any],
    field_name: str,
    binding_ref: _PlannedBindingRef,
) -> None:
    field_path = _vpc_field_path(payload=payload, row=row, field_name=field_name)
    existing_value = _read_payload_field(payload, _format_payload_path(field_path))
    if _has_required_prompt_value(existing_value, type_hint="string"):
        raise RuntimeError(
            f"{_format_payload_path(field_path)} cannot use a planned ref because a literal value is already set."
        )
    target_path = _vpc_binding_target_path(row, field_name)
    component_path = field_path[:3]
    component_node = _get_payload_value(payload, component_path)
    if not isinstance(component_node, dict):
        raise RuntimeError("Generated payload is missing the target infra component mapping.")
    bindings = component_node.setdefault("bindings", {})
    if not isinstance(bindings, dict):
        raise RuntimeError(f"{_format_payload_path(component_path)}.bindings must be a mapping.")
    spec = {
        "source_component": "vpc",
        "source_instance": binding_ref.source_instance,
        "source_output": binding_ref.source_output,
    }
    if binding_ref.key is not None and binding_ref.attribute is not None:
        spec["key"] = binding_ref.key
        spec["attribute"] = binding_ref.attribute
    existing_binding = bindings.get(target_path)
    if existing_binding is not None and existing_binding != spec:
        raise RuntimeError(
            f"{_format_payload_path(component_path)}.bindings.{target_path} already references a different source."
        )
    bindings[target_path] = spec


def _apply_vpc_id_overrides_for_field(
    *,
    payload: dict[str, Any],
    selected_infra: set[str],
    raw_values: list[str] | None,
    option_name: str,
    field_name: str,
    component_ids: frozenset[str],
) -> None:
    bare_values, scoped_values = _parse_vpc_id_overrides(
        raw_values=raw_values,
        option_name=option_name,
    )
    if not bare_values and not scoped_values:
        return
    rows = _selected_infra_rows_for_vpc_override(
        payload=payload,
        selected_infra=selected_infra,
        component_ids=component_ids,
    )
    if bare_values:
        if len(rows) != 1:
            available = ", ".join(
                sorted(
                    component_instance_label(component_type_id(row), component_instance_id(row))
                    for row in rows
                )
            )
            raise RuntimeError(
                f"Bare {option_name} is valid only when exactly one applicable infra component is selected. "
                f"Pass scoped values such as --{option_name.lstrip('-')} {_vpc_override_selector_example()}. "
                + (
                    f"Selected applicable rows: {available}"
                    if available
                    else "No applicable rows are selected."
                )
            )
        _set_vpc_field(payload=payload, row=rows[0], field_name=field_name, value=bare_values[0])
        return

    for selector, value in scoped_values.items():
        row = _resolve_vpc_override_target(
            rows=rows,
            selector=selector,
            option_name=option_name,
        )
        _set_vpc_field(payload=payload, row=row, field_name=field_name, value=value)


def _apply_vpc_ref_overrides_for_field(
    *,
    payload: dict[str, Any],
    selected_infra: set[str],
    raw_values: list[str] | None,
    option_name: str,
    field_name: str,
    component_ids: frozenset[str],
) -> None:
    bare_values, scoped_values = _parse_vpc_id_overrides(
        raw_values=raw_values,
        option_name=option_name,
    )
    if not bare_values and not scoped_values:
        return
    rows = _selected_infra_rows_for_vpc_override(
        payload=payload,
        selected_infra=selected_infra,
        component_ids=component_ids,
    )
    if bare_values:
        if len(rows) != 1:
            available = ", ".join(
                sorted(
                    component_instance_label(component_type_id(row), component_instance_id(row))
                    for row in rows
                )
            )
            raise RuntimeError(
                f"Bare {option_name} is valid only when exactly one applicable infra component is selected. "
                f"Pass scoped values such as --{option_name.lstrip('-')} "
                f"infra:vm@worker="
                f"{'vpc@worker-vpc.network_id' if field_name == 'network_id' else 'vpc@worker-vpc.subnets.worker.id'}. "
                + (
                    f"Selected applicable rows: {available}"
                    if available
                    else "No applicable rows are selected."
                )
            )
        _set_vpc_binding(
            payload=payload,
            row=rows[0],
            field_name=field_name,
            binding_ref=_parse_planned_vpc_ref(
                bare_values[0],
                option_name=option_name,
                field_name=field_name,
            ),
        )
        return

    for selector, value in scoped_values.items():
        row = _resolve_vpc_override_target(
            rows=rows,
            selector=selector,
            option_name=option_name,
        )
        _set_vpc_binding(
            payload=payload,
            row=row,
            field_name=field_name,
            binding_ref=_parse_planned_vpc_ref(
                value,
                option_name=option_name,
                field_name=field_name,
            ),
        )


def _apply_vpc_id_overrides(
    *,
    payload: dict[str, Any],
    selected_infra: set[str],
    network_ids: list[str] | None,
    subnet_ids: list[str] | None,
) -> None:
    _apply_vpc_id_overrides_for_field(
        payload=payload,
        selected_infra=selected_infra,
        raw_values=network_ids,
        option_name="--network-id",
        field_name="network_id",
        component_ids=frozenset(_NETWORK_ATTACHED_INFRA_COMPONENT_IDS),
    )
    _apply_vpc_id_overrides_for_field(
        payload=payload,
        selected_infra=selected_infra,
        raw_values=subnet_ids,
        option_name="--subnet-id",
        field_name="subnet_id",
        component_ids=frozenset(_SUBNET_ATTACHED_INFRA_COMPONENT_IDS),
    )


def _apply_vpc_ref_overrides(
    *,
    payload: dict[str, Any],
    selected_infra: set[str],
    network_refs: list[str] | None,
    subnet_refs: list[str] | None,
) -> None:
    _apply_vpc_ref_overrides_for_field(
        payload=payload,
        selected_infra=selected_infra,
        raw_values=network_refs,
        option_name="--network-ref",
        field_name="network_id",
        component_ids=frozenset(_NETWORK_ATTACHED_INFRA_COMPONENT_IDS),
    )
    _apply_vpc_ref_overrides_for_field(
        payload=payload,
        selected_infra=selected_infra,
        raw_values=subnet_refs,
        option_name="--subnet-ref",
        field_name="subnet_id",
        component_ids=frozenset(_SUBNET_ATTACHED_INFRA_COMPONENT_IDS),
    )


def _apply_app_release_overrides(
    *,
    payload: dict[str, Any],
    selected_apps: set[str],
    selected_app_identities: set[tuple[str, str]] | None = None,
    namespace_overrides: dict[str, str],
    release_name_overrides: dict[str, str],
    version_overrides: dict[str, str] | None = None,
) -> None:
    chart_version_overrides = version_overrides or {}
    if not namespace_overrides and not release_name_overrides and not chart_version_overrides:
        return
    apps_node = payload.get("apps")
    if not isinstance(apps_node, dict):
        raise RuntimeError("Generated payload is missing apps mapping.")
    charts = apps_node.get("charts")
    if not isinstance(charts, list):
        raise RuntimeError("Generated payload is missing apps.charts list.")

    selected_app_ids = {normalize_component_token(item) for item in selected_apps if item}
    selected_identities = (
        {
            (normalize_component_token(chart_id), normalize_component_token(instance_id))
            for chart_id, instance_id in selected_app_identities
            if chart_id and instance_id
        }
        if selected_app_identities is not None
        else None
    )
    by_id: dict[str, list[dict[str, Any]]] = {}
    for item in charts:
        if not isinstance(item, dict):
            continue
        chart_id = normalize_component_token(item.get("id"))
        if not chart_id or chart_id not in selected_app_ids:
            continue
        if (
            selected_identities is not None
            and (
                chart_id,
                component_instance_id(item),
            )
            not in selected_identities
        ):
            continue
        by_id.setdefault(chart_id, []).append(item)

    target_ids = (
        set(namespace_overrides) | set(release_name_overrides) | set(chart_version_overrides)
    )
    for chart_id in sorted(target_ids):
        chart_id = normalize_component_token(chart_id)
        if chart_id not in selected_app_ids:
            raise RuntimeError(
                f"Override target apps component '{chart_id}' is not enabled. "
                "Select it in this command first."
            )
        rows = by_id.get(chart_id, [])
        if not rows:
            raise RuntimeError(
                f"Override target apps component '{chart_id}' was not found in apps.charts."
            )
        for row in rows:
            namespace = namespace_overrides.get(chart_id)
            if namespace is not None:
                row["namespace"] = namespace
            release_name = release_name_overrides.get(chart_id)
            if release_name is not None:
                row["release-name"] = release_name
            chart_version = chart_version_overrides.get(chart_id)
            if chart_version is not None:
                try:
                    row["version"] = _validate_helm_chart_version_value(
                        chart_version,
                        option_name="--app-version",
                    )
                except ValueError as exc:
                    raise RuntimeError(str(exc)) from exc


def _resolve_component_ids_from_tokens(
    *,
    scope: ComponentScope,
    tokens: list[str],
    entries: tuple[ComponentEntry, ...],
    defaults: set[str],
) -> set[str]:
    selectable_entries = [entry for entry in entries if entry.selectable]
    lookup = {entry.id: entry for entry in entries}
    selected: set[str] = set()
    normalized = [token.lower() for token in tokens]

    if len(normalized) == 1:
        keyword = normalized[0]
        if keyword in {"default", "defaults"}:
            return defaults
        if keyword == "all":
            return {entry.id for entry in entries}
        if keyword == "none":
            return set()

    for token in normalized:
        if token.isdigit():
            index = int(token)
            if index < 1 or index > len(selectable_entries):
                raise RuntimeError(
                    f"Invalid {scope} component index '{token}'. Use values between 1 and {len(selectable_entries)}."
                )
            selected.add(selectable_entries[index - 1].id)
            continue

        entry = lookup.get(token)
        if entry is None:
            internal_message = _internal_component_selector_message(
                scope=scope,
                component_id=token,
            )
            if internal_message:
                raise RuntimeError(internal_message)
            available = ", ".join(entry.id for entry in selectable_entries)
            raise RuntimeError(
                f"Unknown {scope} component id '{token}'. Available ids: {available}"
            )
        if not entry.selectable:
            selected.add(entry.id)
            continue
        selected.add(entry.id)

    return selected


def _internal_component_selector_message(*, scope: ComponentScope, component_id: str) -> str:
    if scope != "apps":
        return ""
    normalized = normalize_component_token(component_id)
    if not normalized:
        return ""
    sources = load_component_sources()
    for chart in sources.helm_charts:
        if normalize_component_token(chart.name) != normalized:
            continue
        if chart.selectable:
            return ""
        usage = getattr(chart, "usage", None)
        if getattr(usage, "lifecycle", "") == "transient":
            config_ref = _non_empty_text(getattr(usage, "config_ref", ""))
            config_guidance = (
                f" Configure it through {config_ref} in config.yaml"
                if config_ref
                else " Configure it through `nebius-cxcli acceptance-test benchmark`"
                if normalized == "nccl-test"
                else " Configure it through its catalog-declared runtime flow"
            )
            return (
                f"apps component id '{normalized}' exists in the active catalog but is "
                f"a transient runtime chart, not a selectable persistent app.{config_guidance} "
                "instead of selecting it with --app or component add."
            )
        return (
            f"{scope} component id '{normalized}' exists in the active catalog but "
            "is internal and cannot be selected directly."
        )
    return ""


def _component_selector_label(entry: ComponentEntry, *, scope: ComponentScope) -> str:
    base = entry.id
    if entry.group:
        return f"{entry.group} >> {base}"
    return base


def _component_instance_selector_label(
    entry: ComponentEntry,
    *,
    instance_id: str,
) -> str:
    base = _component_selector_label(entry, scope=entry.scope)
    if instance_id == entry.id:
        return base
    return f"{base} @ {instance_id}"


def _component_selection_summary(
    *,
    selected: set[str],
    entries: tuple[ComponentEntry, ...],
) -> str:
    labels = _component_selection_labels(selected=selected, entries=entries)
    return ", ".join(labels) if labels else "(none)"


def _component_selection_labels(
    *,
    selected: set[str],
    entries: tuple[ComponentEntry, ...],
) -> list[str]:
    if not selected:
        return []
    entry_by_id = {entry.id: entry for entry in entries}
    labels: list[str] = []
    for component_id in sorted(selected):
        entry = entry_by_id.get(component_id)
        labels.append(entry.id if entry is not None else component_id)
    return labels


def _component_selection_block(
    *,
    infra_labels: Sequence[str],
    app_labels: Sequence[str],
    current_label: str = "",
    current_scope: ComponentScope | str | None = None,
) -> str:
    if current_label:
        scope_label = str(current_scope).title() if current_scope is not None else "Component"
        return (
            "[bold cyan]Wizard context:[/bold cyan] "
            "[dim]Current:[/dim] "
            f"[bold magenta]{escape(scope_label)}[/bold magenta] "
            "[dim]/[/dim] "
            f"[bold green]{escape(current_label)}[/bold green]"
        )

    lines = ["Component selections:"]

    def _append_section(
        title: str,
        labels: Sequence[str],
        *,
        current: str = "",
    ) -> None:
        lines.append(f"  {title}:")
        if not labels:
            lines.append("    - (none)")
            return
        for label in labels:
            if current and label == current:
                lines.append(f"    * {escape(label)} (current)")
                continue
            lines.append(f"    - {escape(label)}")

    _append_section(
        "Infra",
        infra_labels,
        current=current_label if current_scope == "infra" else "",
    )
    _append_section(
        "Apps",
        app_labels,
        current=current_label if current_scope == "apps" else "",
    )
    return "\n".join(lines)


def _print_component_scope_selection_summary(
    *,
    scope: ComponentScope,
    selected: set[str],
    entries: tuple[ComponentEntry, ...],
) -> None:
    summary = _component_selection_summary(selected=selected, entries=entries)
    console.print(f"[dim]Selected {scope} components: {escape(summary)}[/dim]")


def _print_component_selection_summary(
    *,
    selected_infra: set[str],
    selected_apps: set[str],
    infra_entries: tuple[ComponentEntry, ...],
    app_entries: tuple[ComponentEntry, ...],
    payload: dict[str, Any] | None = None,
) -> None:
    if payload is None:
        infra_labels = _component_selection_labels(
            selected=selected_infra,
            entries=infra_entries,
        )
        app_labels = _component_selection_labels(
            selected=selected_apps,
            entries=app_entries,
        )
    else:
        infra_labels, app_labels = _payload_component_selection_labels(
            payload=payload,
            selected_infra=selected_infra,
            selected_apps=selected_apps,
            infra_entries=infra_entries,
            app_entries=app_entries,
        )
    console.print(_component_selection_block(infra_labels=infra_labels, app_labels=app_labels))


def _app_display_target_ref(payload: Mapping[str, Any], row: Mapping[str, Any]) -> str:
    target_ref = app_chart_target_ref(row)
    if target_ref:
        return target_ref
    instance_id = component_instance_id(row)
    return instance_id if instance_id in set(enabled_cluster_target_refs(payload)) else ""


def _app_component_selection_label(payload: Mapping[str, Any], row: Mapping[str, Any]) -> str:
    app_id = component_type_id(row)
    instance_id = component_instance_id(row)
    target_ref = _app_display_target_ref(payload, row)
    if app_id and target_ref:
        return f"{app_id} on {target_ref}"
    return component_instance_label(app_id, instance_id)


def _payload_component_selection_labels(
    *,
    payload: dict[str, Any],
    selected_infra: set[str],
    selected_apps: set[str],
    infra_entries: tuple[ComponentEntry, ...],
    app_entries: tuple[ComponentEntry, ...],
) -> tuple[list[str], list[str]]:
    infra_entry_ids = {entry.id for entry in infra_entries if entry.id}
    app_entry_ids = {entry.id for entry in app_entries if entry.id}
    selected_infra_ids = {normalize_component_token(item) for item in selected_infra}
    infra_labels: list[str] = []
    for row in _dynamic_enabled_infra_component_rows(payload):
        component_id = component_type_id(row)
        if infra_entry_ids and component_id not in infra_entry_ids:
            continue
        instance_id = component_instance_id(row)
        exact_selector = component_instance_label(component_id, instance_id)
        if exact_selector not in selected_infra_ids and instance_id not in selected_infra_ids:
            continue
        infra_labels.append(exact_selector)

    selected_app_ids = {normalize_component_token(item) for item in selected_apps}
    exact_selector_mode = any("@" in token for token in selected_app_ids)
    app_labels: list[str] = []
    for row in _dynamic_enabled_app_chart_rows(payload):
        app_id = component_type_id(row)
        if app_entry_ids and app_id not in app_entry_ids:
            continue
        instance_id = component_instance_id(row)
        exact_selector = component_instance_label(app_id, instance_id)
        if (
            exact_selector not in selected_app_ids
            and app_id not in selected_app_ids
            and (exact_selector_mode or instance_id not in selected_app_ids)
        ):
            continue
        app_labels.append(_app_component_selection_label(payload, row))
    return infra_labels, app_labels


def _enabled_app_instance_labels(
    payload: dict[str, Any],
    *,
    app_id: str = "",
) -> tuple[str, ...]:
    apps = payload.get("apps")
    if not isinstance(apps, Mapping):
        return ()
    charts = apps.get("charts")
    if not isinstance(charts, list):
        return ()

    normalized_app_id = normalize_component_token(app_id)
    labels: list[str] = []
    seen: set[str] = set()
    for row in charts:
        if not isinstance(row, Mapping) or not bool(row.get("enabled", False)):
            continue
        chart_id = component_type_id(row)
        if normalized_app_id and chart_id != normalized_app_id:
            continue
        instance_id = component_instance_id(row)
        label = component_instance_label(chart_id, instance_id)
        if not label or label in seen:
            continue
        labels.append(label)
        seen.add(label)
    return tuple(labels)


def _new_enabled_app_instance_labels(
    payload: dict[str, Any],
    *,
    before_labels: set[str],
    app_ids: Sequence[str],
) -> tuple[str, ...]:
    normalized_app_ids = {
        normalize_component_token(item) for item in app_ids if normalize_component_token(item)
    }
    if not normalized_app_ids:
        return ()
    apps = payload.get("apps")
    charts = apps.get("charts") if isinstance(apps, Mapping) else None
    if not isinstance(charts, list):
        return ()
    labels: list[str] = []
    target_scoped_labels: list[str] = []
    seen: set[str] = set()
    target_refs = tuple(enabled_cluster_target_refs(payload))
    for row in charts:
        if not isinstance(row, Mapping) or not bool(row.get("enabled", False)):
            continue
        app_id = component_type_id(row)
        if app_id not in normalized_app_ids:
            continue
        instance_id = component_instance_id(row)
        if instance_id == app_id and len(target_refs) == 1:
            label = component_instance_label(app_id, target_refs[0])
        else:
            label = component_instance_label(app_id, instance_id)
        if not label or label in before_labels or label in seen:
            continue
        labels.append(label)
        if "@" in label:
            target_scoped_labels.append(label)
        seen.add(label)
    return tuple(target_scoped_labels or labels)


def _target_aware_added_app_labels(
    payload: dict[str, Any],
    labels: Sequence[str],
) -> list[str]:
    apps = payload.get("apps")
    charts = apps.get("charts") if isinstance(apps, Mapping) else None
    if not isinstance(charts, list):
        return list(labels)

    enabled_labels_by_app: dict[str, list[str]] = {}
    for row in charts:
        if not isinstance(row, Mapping) or not bool(row.get("enabled", False)):
            continue
        app_id = component_type_id(row)
        instance_id = component_instance_id(row)
        label = component_instance_label(app_id, instance_id)
        if not app_id or not label:
            continue
        enabled_labels_by_app.setdefault(app_id, []).append(label)

    resolved: list[str] = []
    for raw_label in labels:
        label = normalize_component_token(raw_label)
        if "@" in label:
            replacement = label
        else:
            scoped = [
                candidate for candidate in enabled_labels_by_app.get(label, []) if "@" in candidate
            ]
            replacement = scoped[0] if len(scoped) == 1 else label
        if replacement and replacement not in resolved:
            resolved.append(replacement)
    return resolved


def _ensure_mysterybox_eso_app_dependency_selection(
    payload: dict[str, Any],
    *,
    selected_apps: set[str],
    app_entries: tuple[ComponentEntry, ...],
) -> tuple[set[str], tuple[str, ...]]:
    before_selected_apps = set(selected_apps)
    before_labels = set(_enabled_app_instance_labels(payload, app_id=EXTERNAL_SECRETS_APP_ID))
    changed = ensure_mysterybox_eso_app_rows(payload, app_entries=app_entries)
    after_selected_apps = _enabled_ids_from_runtime_payload(payload=payload, entries=app_entries)
    external_secrets_was_auto_selected = (
        EXTERNAL_SECRETS_APP_ID in after_selected_apps
        and EXTERNAL_SECRETS_APP_ID not in before_selected_apps
    )
    if not changed and not external_secrets_was_auto_selected:
        return selected_apps, ()
    after_labels = set(_enabled_app_instance_labels(payload, app_id=EXTERNAL_SECRETS_APP_ID))
    auto_enabled_labels = after_labels - before_labels
    if external_secrets_was_auto_selected and not auto_enabled_labels:
        auto_enabled_labels = after_labels
    return (
        after_selected_apps,
        tuple(sorted(auto_enabled_labels)),
    )


def _print_mysterybox_eso_app_dependency_adjustment(app_labels: tuple[str, ...]) -> None:
    if not app_labels:
        return
    console.print(
        f"{warning_markup('Adjusted component selection:')} enabling "
        + ", ".join(f"'apps:{label}'" for label in app_labels)
        + " because selected MysteryBox-to-Kubernetes sync requires the External Secrets "
        "Operator controller."
    )


def _ensure_nfs_csi_app_dependency_selection(
    payload: dict[str, Any],
    *,
    selected_apps: set[str],
    app_entries: tuple[ComponentEntry, ...],
) -> tuple[set[str], tuple[str, ...]]:
    before_selected_apps = set(selected_apps)
    before_labels = set(_enabled_app_instance_labels(payload, app_id=NFS_CSI_APP_ID))
    changed = ensure_nfs_csi_app_rows(payload, app_entries=app_entries)
    after_selected_apps = _enabled_ids_from_runtime_payload(payload=payload, entries=app_entries)
    nfs_csi_was_auto_selected = (
        NFS_CSI_APP_ID in after_selected_apps and NFS_CSI_APP_ID not in before_selected_apps
    )
    if not changed and not nfs_csi_was_auto_selected:
        return selected_apps, ()
    after_labels = set(_enabled_app_instance_labels(payload, app_id=NFS_CSI_APP_ID))
    auto_enabled_labels = after_labels - before_labels
    if nfs_csi_was_auto_selected and not auto_enabled_labels:
        auto_enabled_labels = after_labels
    return after_selected_apps, tuple(sorted(auto_enabled_labels))


def _print_nfs_csi_app_dependency_adjustment(app_labels: tuple[str, ...]) -> None:
    if not app_labels:
        return
    console.print(
        f"{warning_markup('Adjusted component selection:')} enabling "
        + ", ".join(f"'apps:{label}'" for label in app_labels)
        + " because VM-backed NFS for MK8s requires the NFS CSI driver."
    )


def _materialize_soperator_child_chart_secret_dependencies(
    payload: dict[str, Any],
    *,
    selected_apps: set[str],
    app_entries: tuple[ComponentEntry, ...],
) -> tuple[set[str], tuple[str, ...]]:
    """Materialize Soperator child values, then persist any ESO app dependency."""
    materialize_soperator_child_chart_values(payload)
    normalize_mysterybox_eso_project_settings(payload)
    return _ensure_mysterybox_eso_app_dependency_selection(
        payload,
        selected_apps=selected_apps,
        app_entries=app_entries,
    )


def _expand_soperator_component_selection(
    *,
    selected_infra: set[str],
    selected_apps: set[str],
    infra_entries: tuple[ComponentEntry, ...],
    install_mode: str | None = None,
) -> set[str]:
    if _SOPERATOR_APP_ID not in selected_apps:
        return selected_infra
    if (
        install_mode or _default_soperator_install_mode()
    ) == _SOPERATOR_INSTALL_MODE_ONBOARD_EXISTING_CLUSTER:
        return selected_infra
    available_infra = {entry.id for entry in infra_entries}
    expanded = set(selected_infra)
    for component_id in _SOPERATOR_REQUIRED_INFRA_COMPONENT_IDS:
        if component_id in available_infra:
            expanded.add(component_id)
    return expanded


def _prune_soperator_onboarding_infra_selection(
    *,
    selected_infra: set[str],
    selected_apps: set[str],
    install_mode: str | None,
    new_infra: set[str],
    existing_infra: set[str] | None = None,
) -> tuple[set[str], tuple[str, ...]]:
    if _SOPERATOR_APP_ID not in selected_apps:
        return selected_infra, ()
    if install_mode != _SOPERATOR_INSTALL_MODE_ONBOARD_EXISTING_CLUSTER:
        return selected_infra, ()

    existing = existing_infra or set()
    skipped = tuple(
        component_id
        for component_id in _SOPERATOR_REQUIRED_INFRA_COMPONENT_IDS
        if component_id in new_infra
    )
    if not skipped:
        return selected_infra, ()

    pruned = set(selected_infra)
    for component_id in skipped:
        if component_id not in existing:
            pruned.discard(component_id)
    return pruned, skipped


def _print_soperator_onboarding_infra_adjustment(component_ids: tuple[str, ...]) -> None:
    if not component_ids:
        return
    console.print(
        f"{warning_markup('Adjusted component selection:')} skipping "
        + ", ".join(f"'infra:{component_id}'" for component_id in component_ids)
        + " because 'apps:soperator' install_mode=onboard-existing-cluster "
        "uses an external MK8s target and does not create Terraform MK8s/SFS resources."
    )


def _expand_soperator_app_selection(
    *,
    selected_apps: set[str],
    app_entries: tuple[ComponentEntry, ...],
) -> set[str]:
    if _SOPERATOR_APP_ID not in selected_apps:
        return selected_apps
    available_apps = {entry.id for entry in app_entries}
    expanded = set(selected_apps)
    for app_id in _SOPERATOR_REQUIRED_APP_COMPONENT_IDS:
        if app_id in available_apps:
            expanded.add(app_id)
    return expanded


def _print_soperator_selection_adjustments(
    *,
    selected_infra_before: set[str],
    selected_apps_before: set[str],
    selected_infra_after: set[str],
    selected_apps_after: set[str],
    install_mode: str | None = None,
) -> None:
    if _SOPERATOR_APP_ID not in selected_apps_after:
        return
    resolved_install_mode = install_mode or _default_soperator_install_mode()
    added_required_infra = tuple(
        component_id
        for component_id in _SOPERATOR_REQUIRED_INFRA_COMPONENT_IDS
        if component_id in selected_infra_after and component_id not in selected_infra_before
    )
    if added_required_infra and resolved_install_mode == _SOPERATOR_INSTALL_MODE_PRODUCTION:
        console.print(
            f"{warning_markup('Adjusted component selection:')} enabling "
            + ", ".join(f"'infra:{component_id}'" for component_id in added_required_infra)
            + " because 'apps:soperator' install_mode=production-cluster creates "
            "the complete MK8s+SFS+Soperator bundle."
        )

    added_required_apps = tuple(
        app_id
        for app_id in _SOPERATOR_REQUIRED_APP_COMPONENT_IDS
        if app_id in selected_apps_after and app_id not in selected_apps_before
    )
    if added_required_apps:
        console.print(
            f"{warning_markup('Adjusted component selection:')} enabling "
            + ", ".join(f"'apps:{app_id}'" for app_id in added_required_apps)
            + " because 'apps:soperator' requires cert-manager for webhook "
            "certificate automation."
        )


def _soperator_install_mode_choices() -> list[OptionChoice]:
    chart = helm_chart_source_by_id(_SOPERATOR_APP_ID)
    wizard_fields = getattr(chart, "wizard_fields", {}) or {}
    install_mode_spec = wizard_fields.get(_SOPERATOR_INSTALL_MODE_FIELD)
    choices: list[OptionChoice] = []
    sources = install_mode_spec.get("sources") if isinstance(install_mode_spec, Mapping) else None
    if isinstance(sources, list):
        for source in sources:
            if not isinstance(source, Mapping):
                continue
            if str(source.get("source", "")).strip().lower() != "static":
                continue
            values = source.get("values")
            if not isinstance(values, list):
                continue
            for raw in values:
                if isinstance(raw, Mapping):
                    value = normalize_component_token(raw.get("value"))
                    label = _non_empty_text(raw.get("label")) or value
                else:
                    value = normalize_component_token(raw)
                    label = value
                if value in _SOPERATOR_INSTALL_MODES:
                    choices.append(OptionChoice(value=value, label=label))
    if choices:
        return choices
    return [
        OptionChoice(
            value=_SOPERATOR_INSTALL_MODE_PRODUCTION,
            label="Create complete production Soperator cluster (MK8s + SFS + Soperator)",
        )
    ]


def _prompt_soperator_install_mode(*, default: str | None = None) -> str:
    current = default or _default_soperator_install_mode()
    while True:
        updated, should_stop = _prompt_scalar_override(
            _SOPERATOR_INSTALL_MODE_FIELD,
            current,
            choices=_soperator_install_mode_choices(),
            type_hint="string",
            required=True,
        )
        if should_stop:
            raise _WizardQuitRequested
        if _wizard_backtrack_requested(updated):
            return (
                current
                if current in _SOPERATOR_INSTALL_MODES
                else _default_soperator_install_mode()
            )
        mode = normalize_component_token(updated)
        if mode in _SOPERATOR_INSTALL_MODES:
            return mode
        console.print(
            f"{error_markup('Invalid value')} for '{_SOPERATOR_INSTALL_MODE_FIELD}'. "
            "Choose one of the listed Soperator install modes."
        )


def _soperator_profile_choices() -> list[OptionChoice]:
    current_default = _default_soperator_profile_name()
    _settings_default, profiles = _soperator_nodesets_profiles()
    choices: list[OptionChoice] = []
    for name, profile in profiles.items():
        profile_name = str(name).strip()
        if not profile_name:
            continue
        wizard = profile.get("wizard") if isinstance(profile, Mapping) else None
        label = (
            _non_empty_text(wizard.get("label")) if isinstance(wizard, Mapping) else ""
        ) or profile_name
        choices.append(
            OptionChoice(
                value=profile_name,
                label=label,
                recommended=profile_name == current_default,
            )
        )
    return choices


def _prompt_soperator_profile(*, default: str | None = None) -> str:
    current = default or _default_soperator_profile_name()
    _settings_default, profiles = _soperator_nodesets_profiles()
    while True:
        updated, should_stop = _prompt_scalar_override(
            "profile",
            current,
            choices=_soperator_profile_choices(),
            type_hint="string",
            required=True,
        )
        if should_stop:
            raise _WizardQuitRequested
        if _wizard_backtrack_requested(updated):
            return current if current in profiles else _default_soperator_profile_name()
        profile = _non_empty_text(updated)
        if profile in profiles:
            return profile
        available = ", ".join(sorted(str(name) for name in profiles)) or "(none)"
        console.print(
            f"{error_markup('Invalid value')} for 'profile'. "
            f"Choose one of the listed Soperator profiles: {available}."
        )


def _apply_soperator_install_mode_to_payload(payload: dict[str, Any], *, mode: str) -> None:
    if mode not in _SOPERATOR_INSTALL_MODES:
        return
    apps_node = payload.get("apps")
    charts = apps_node.get("charts") if isinstance(apps_node, Mapping) else None
    if not isinstance(charts, list):
        return
    for row in charts:
        if not isinstance(row, dict) or not bool(row.get("enabled", False)):
            continue
        if component_type_id(row) == _SOPERATOR_APP_ID:
            row[_SOPERATOR_INSTALL_MODE_FIELD] = mode


def _apply_soperator_profile_to_payload(payload: dict[str, Any], *, profile: str) -> None:
    if not profile:
        return
    _settings_default, profiles = _soperator_nodesets_profiles()
    if profile not in profiles:
        return
    apps_node = payload.get("apps")
    charts = apps_node.get("charts") if isinstance(apps_node, Mapping) else None
    if not isinstance(charts, list):
        return
    for row in charts:
        if not isinstance(row, dict) or not bool(row.get("enabled", False)):
            continue
        if component_type_id(row) == _SOPERATOR_APP_ID:
            row["profile"] = profile


def _soperator_catalog_pinned_versions() -> tuple[str, str]:
    chart = helm_chart_source_by_id(_SOPERATOR_APP_ID)
    chart_version = _non_empty_text(getattr(chart, "version", ""))
    app_version = ""
    local_source = getattr(chart, "local_source", None)
    local_path = _non_empty_text(getattr(local_source, "path", ""))
    if local_path:
        chart_yaml = (resolve_component_sources_file().parent / local_path / "Chart.yaml").resolve()
        if chart_yaml.exists():
            with suppress(Exception):
                payload = yaml.safe_load(chart_yaml.read_text(encoding="utf-8")) or {}
                if isinstance(payload, Mapping):
                    chart_version = chart_version or _non_empty_text(payload.get("version"))
                    app_version = _non_empty_text(payload.get("appVersion"))
    return chart_version, app_version


def _soperator_onboarding_target_version_default() -> str:
    default_version = _soperator_upgrade_catalog_to_version_default()
    if default_version:
        return default_version
    chart_version, _app_version = _soperator_catalog_pinned_versions()
    return chart_version


def _soperator_onboarding_target_app_version_for_chart(chart_version: str) -> str:
    catalog_chart_version, catalog_app_version = _soperator_catalog_pinned_versions()
    if _non_empty_text(chart_version) == _non_empty_text(catalog_chart_version):
        return catalog_app_version
    return ""


def _soperator_target_chart_source() -> tuple[str, str]:
    chart = helm_chart_source_by_id(_SOPERATOR_APP_ID)
    if chart is None:
        raise RuntimeError("Soperator chart source is not declared in component_sources.yaml.")
    portable = getattr(chart, "portable_source", None)
    chart_name = (
        _non_empty_text(getattr(portable, "chart_name", ""))
        or _non_empty_text(getattr(chart, "chart_name", ""))
        or _SOPERATOR_APP_ID
    )
    chart_repo = _non_empty_text(getattr(portable, "repo", "")) or _non_empty_text(
        getattr(chart, "repo", "")
    )
    if not chart_repo:
        raise RuntimeError("Soperator chart source is missing source.portable.repo.")
    return chart_name, chart_repo


def _validate_soperator_onboarding_target_chart_version(
    value: object,
    *,
    validate_sources: bool,
) -> str:
    version = _validate_helm_chart_version_value(
        str(value or ""),
        option_name="--to-chart-version",
    )
    if not validate_sources:
        return version
    default_version = _soperator_onboarding_target_version_default()
    if version == default_version:
        return version
    chart_name, chart_repo = _soperator_target_chart_source()
    issues = _resolve_helm_chart_validation_issues(
        chart_name=chart_name,
        chart_repo=chart_repo,
        chart_version=version,
        chart_meta_cache={},
    )
    if issues:
        raise RuntimeError(
            "Soperator target chart version validation failed for "
            f"'{version}':\n  - " + "\n  - ".join(issues)
        )
    return version


def _warn_if_soperator_onboarding_target_appears_lower(
    *,
    target_version: str,
    default_version: str,
) -> None:
    comparison = _compare_chart_versions(target_version, default_version)
    if comparison is None or comparison >= 0:
        return
    console.print(
        f"{warning_markup('WARNING:', bold=True)} selected Soperator target chart version "
        f"{target_version} appears lower than the catalog default {default_version}. "
        "cxcli will record this accepted onboarding target, but Helm/Soperator "
        "downgrades are not guaranteed safe; review release notes, CRDs/schema "
        "migrations, application state, and backups before executing.",
        soft_wrap=True,
    )


def _resolve_soperator_onboarding_target_chart_version(
    *,
    to_chart_version: str | None,
    interactive: bool,
    validate_sources: bool,
) -> str:
    default_version = _soperator_onboarding_target_version_default()
    if not default_version:
        raise RuntimeError(
            "Soperator onboarding could not determine the catalog-pinned target "
            "chart version from component_sources.yaml."
        )
    raw_version = _non_empty_text(to_chart_version)
    if not raw_version and interactive:
        raw_version, should_stop = _prompt_scalar_override(
            "deploy.targets[].soperator_onboarding.target_version",
            default_version,
            prompt_hint="catalog default",
            type_hint="string",
            required=True,
        )
        if should_stop:
            raise _WizardQuitRequested
        if _wizard_backtrack_requested(raw_version):
            raw_version = default_version
    selected_version = raw_version or default_version
    version = _validate_soperator_onboarding_target_chart_version(
        selected_version,
        validate_sources=validate_sources,
    )
    _warn_if_soperator_onboarding_target_appears_lower(
        target_version=version,
        default_version=default_version,
    )
    return version


def _validate_soperator_onboarding_target_k8s_version(value: object) -> str:
    text = _non_empty_text(value)
    if not text:
        return ""
    try:
        return parse_k8s_version(text).minor_text
    except ValueError as exc:
        raise RuntimeError(str(exc)) from exc


def _soperator_onboarding_snapshot_control_plane_k8s_version(
    snapshot: Mapping[str, Any] | None,
) -> str:
    return soperator_discovery_snapshot_control_plane_k8s_version(snapshot)


def _soperator_onboarding_next_k8s_minor(current_version: str, max_version: str) -> str:
    try:
        current = parse_k8s_version(current_version)
        maximum = parse_k8s_version(max_version)
    except ValueError:
        return ""
    if (current.major, current.minor) > (maximum.major, maximum.minor):
        raise RuntimeError(
            "Discovered external MK8s Kubernetes version "
            f"{current.minor_text} is newer than the cxcli-supported external "
            f"onboarding target {maximum.minor_text}. Upgrade cxcli before running "
            "external Soperator onboarding for this cluster; cxcli will not generate "
            "an external node-template target that it cannot validate."
        )
    if current.major != maximum.major:
        return ""
    if current.minor >= maximum.minor:
        return current.minor_text
    return f"{current.major}.{current.minor + 1}"


def _soperator_onboarding_target_k8s_version_default(
    snapshot: Mapping[str, Any] | None = None,
) -> str:
    latest_supported = ONBOARDING_EXTERNAL_NODE_TEMPLATE_TARGET_K8S_VERSION
    current_version = _soperator_onboarding_snapshot_control_plane_k8s_version(snapshot)
    next_minor = _soperator_onboarding_next_k8s_minor(current_version, latest_supported)
    return next_minor or latest_supported


def _resolve_soperator_onboarding_target_k8s_version(
    *,
    to_k8s_version: str | None,
    interactive: bool,
    required: bool,
    snapshot: Mapping[str, Any] | None = None,
) -> str:
    default_version = _soperator_onboarding_target_k8s_version_default(snapshot)
    raw_version = _non_empty_text(to_k8s_version)
    if not raw_version and interactive and required:
        current_version = _soperator_onboarding_snapshot_control_plane_k8s_version(snapshot)
        prompt_hint = "next supported minor" if current_version else "Nebius latest supported minor"
        raw_version, should_stop = _prompt_scalar_override(
            "deploy.targets[].soperator_onboarding.node_template_upgrade.target_k8s_version",
            default_version,
            prompt_hint=prompt_hint,
            type_hint="string",
            required=True,
        )
        if should_stop:
            raise _WizardQuitRequested
        if _wizard_backtrack_requested(raw_version):
            raw_version = default_version
    if not raw_version and required:
        raise RuntimeError(
            "External Soperator onboarding selected an external MK8s node-template upgrade. "
            f"Pass --to-k8s-version with the next Kubernetes minor target, for example {default_version}. "
            "cxcli will not silently choose a Kubernetes target for this accepted upgrade plan."
        )
    return _validate_soperator_onboarding_target_k8s_version(raw_version or default_version)


def _soperator_support_finding_evidence(finding: Mapping[str, Any]) -> Mapping[str, Any]:
    evidence = finding.get("evidence")
    return evidence if isinstance(evidence, Mapping) else {}


def _soperator_support_finding_label(finding: Mapping[str, Any]) -> str:
    evidence = _soperator_support_finding_evidence(finding)
    rule_id = _non_empty_text(evidence.get("rule_id")) or "unknown-rule"
    status = _non_empty_text(finding.get("status")) or "unknown"
    source_version = _non_empty_text(evidence.get("source_version")) or "unknown"
    target_version = _non_empty_text(evidence.get("target_version")) or "unknown"
    target_k8s = _non_empty_text(evidence.get("target_k8s_version")) or "unknown"
    return (
        f"status={status}, rule={rule_id}, source Soperator={source_version}, "
        f"target Soperator={target_version}, target Kubernetes={target_k8s}"
    )


def _soperator_support_policy_failure_message(
    report: Mapping[str, Any] | Any,
    *,
    command_name: str,
) -> str:
    for finding in soperator_upgrade_support_findings(report):
        status = _non_empty_text(finding.get("status"))
        if status not in SOPERATOR_UPGRADE_SUPPORT_REJECT_STATUSES:
            continue
        message = _non_empty_text(finding.get("message"))
        return (
            "Unsupported Soperator/Kubernetes upgrade path for "
            f"{command_name}: {_soperator_support_finding_label(finding)}. "
            f"Reason: {message or 'the path is not in the committed cxcli upgrade-path policy'}. "
            "Use the cxcli-pinned Soperator target with provider-supported Kubernetes "
            "minor hops, or rerun with --allow-unsupported-soperator-upgrade-path for "
            "an explicit advanced/testing override after validation. This override "
            "does not bypass Kubernetes minor-version hop validation, Nebius API "
            "validation, protected-state checks, backup checks, quota checks, or other "
            "safety preflights."
        )
    return ""


def _soperator_support_policy_has_reject_status(report: Mapping[str, Any] | Any) -> bool:
    return any(
        _non_empty_text(finding.get("status")) in SOPERATOR_UPGRADE_SUPPORT_REJECT_STATUSES
        for finding in soperator_upgrade_support_findings(report)
    )


def _soperator_support_override_report_mapping(report: Mapping[str, Any]) -> dict[str, Any]:
    next_report = copy.deepcopy(to_plain_data(report))
    findings = next_report.get("findings")
    if not isinstance(findings, list):
        return next_report
    for finding in findings:
        if not isinstance(finding, dict):
            continue
        if _non_empty_text(finding.get("layer")) != SOPERATOR_UPGRADE_SUPPORT_LAYER:
            continue
        if _non_empty_text(finding.get("status")) not in SOPERATOR_UPGRADE_SUPPORT_REJECT_STATUSES:
            continue
        evidence = finding.setdefault("evidence", {})
        if not isinstance(evidence, dict):
            evidence = {}
            finding["evidence"] = evidence
        evidence["override_used"] = True
        evidence["original_severity"] = finding.get("severity")
        finding["severity"] = "recommended"
        finding["message"] = (
            "Override accepted for unsupported Soperator upgrade path. "
            + _non_empty_text(finding.get("message"))
        )
    return next_report


def _enforce_soperator_support_policy_for_report(
    report: Mapping[str, Any] | Any,
    *,
    allow_unsupported_soperator_upgrade_path: bool,
    command_name: str,
    dry_run: bool = False,
) -> None:
    if not soperator_upgrade_support_requires_override(report):
        return
    if allow_unsupported_soperator_upgrade_path:
        return
    if dry_run:
        return
    raise RuntimeError(_soperator_support_policy_failure_message(report, command_name=command_name))


def _soperator_support_policy_plan_lines(
    report: Mapping[str, Any] | Any,
    *,
    reject_disposition: str = "execution blocked",
    label: str = "Soperator upgrade path",
    rejection_subject: str = "Soperator upgrade-path rejection",
    include_messages: bool = True,
) -> tuple[str, ...]:
    lines: list[str] = []
    for finding in soperator_upgrade_support_findings(report):
        message = _non_empty_text(finding.get("message"))
        prefix = f"- {label}: "
        if _non_empty_text(finding.get("status")) in SOPERATOR_UPGRADE_SUPPORT_REJECT_STATUSES:
            evidence = _soperator_support_finding_evidence(finding)
            override_used = evidence.get("override_used") is True
            disposition = "override accepted" if override_used else reject_disposition
            prefix = f"- {label} ({disposition}): "
        elif _non_empty_text(finding.get("status")) == "supported_with_warning":
            prefix = f"- {label} warning: "
        lines.append(prefix + _soperator_support_finding_label(finding))
        if message and include_messages:
            lines.append(f"  - {message}")
        if _non_empty_text(finding.get("status")) in SOPERATOR_UPGRADE_SUPPORT_REJECT_STATUSES:
            lines.append(
                "  - Override scope: --allow-unsupported-soperator-upgrade-path only "
                f"bypasses this {rejection_subject}; Kubernetes minor-hop "
                "validation, backup, quota, protected-state, and other safety preflights "
                "still apply."
            )
    return tuple(lines)


def _soperator_discovery_support_evidence(
    report: Mapping[str, Any] | Any,
) -> Mapping[str, Any]:
    for finding in soperator_upgrade_support_findings(report):
        evidence = _soperator_support_finding_evidence(finding)
        if evidence:
            return evidence
    return {}


def _soperator_discovery_support_recommended_order(
    report: Mapping[str, Any] | Any,
) -> Mapping[str, Any]:
    recommended_order = _soperator_discovery_support_evidence(report).get("recommended_order")
    return recommended_order if isinstance(recommended_order, Mapping) else {}


def _soperator_discovery_report_value(
    report: Mapping[str, Any] | Any,
    key: str,
) -> str:
    if isinstance(report, Mapping):
        return _non_empty_text(report.get(key))
    return _non_empty_text(getattr(report, key, ""))


def _soperator_discovery_k8s_version_tuple(version: str) -> tuple[int, int] | None:
    try:
        parsed = parse_k8s_version(version)
    except ValueError:
        return None
    return (parsed.major, parsed.minor)


def _soperator_discovery_k8s_at_least(version: str, minimum: str) -> bool:
    left = _soperator_discovery_k8s_version_tuple(version)
    right = _soperator_discovery_k8s_version_tuple(minimum)
    if left is None or right is None:
        return False
    return left >= right


def _soperator_discovery_k8s_hops(
    current_version: str,
    target_version: str,
) -> tuple[str, ...]:
    try:
        current = parse_k8s_version(current_version)
        target = parse_k8s_version(target_version)
    except ValueError:
        values = [_non_empty_text(current_version), _non_empty_text(target_version)]
        return tuple(dict.fromkeys(value for value in values if value))
    if current.major != target.major or current.minor > target.minor:
        values = [current.minor_text, target.minor_text]
        return tuple(dict.fromkeys(value for value in values if value))
    return tuple(f"{current.major}.{minor}" for minor in range(current.minor, target.minor + 1))


def _soperator_discovery_support_path_values(
    report: Mapping[str, Any] | Any,
) -> tuple[str, str, str, str]:
    evidence = _soperator_discovery_support_evidence(report)
    source_soperator = _non_empty_text(evidence.get("source_version"))
    if not source_soperator:
        source_soperator = _soperator_discovery_report_value(report, "source_version")
    target_soperator = _non_empty_text(evidence.get("target_version"))
    if not target_soperator:
        target_soperator = _soperator_discovery_report_value(report, "target_version")
    current_k8s = _non_empty_text(evidence.get("current_k8s_version"))
    if not current_k8s:
        current_k8s = _soperator_discovery_report_value(report, "current_k8s_version")
    target_k8s = _non_empty_text(evidence.get("target_k8s_version"))
    if not target_k8s:
        target_k8s = _soperator_discovery_report_value(report, "target_k8s_version")
    return source_soperator, target_soperator, current_k8s, target_k8s


def _soperator_discovery_soperator_hops(
    *,
    source_soperator: str,
    target_soperator: str,
) -> tuple[str, ...]:
    values = [_non_empty_text(source_soperator), _non_empty_text(target_soperator)]
    return tuple(dict.fromkeys(value for value in values if value))


def _soperator_discovery_upgrade_order_steps(
    *,
    k8s_hops: tuple[str, ...],
    soperator_hops: tuple[str, ...],
    soperator_after_k8s_min: str,
) -> tuple[str, ...]:
    if not k8s_hops and not soperator_hops:
        return ()
    if not soperator_after_k8s_min or len(soperator_hops) < 2:
        steps: list[str] = []
        if len(soperator_hops) > 1:
            steps.append(f"Soperator {' -> '.join(soperator_hops)}")
        if len(k8s_hops) > 1:
            steps.append(f"Kubernetes {' -> '.join(k8s_hops)}")
        if not steps:
            return ()
        return ("  - Recommended order: " + "; ".join(steps) + ".",)
    staging_index = next(
        (
            index
            for index, hop in enumerate(k8s_hops)
            if _soperator_discovery_k8s_at_least(hop, soperator_after_k8s_min)
        ),
        None,
    )
    if staging_index is None:
        return _soperator_discovery_upgrade_order_steps(
            k8s_hops=k8s_hops,
            soperator_hops=soperator_hops,
            soperator_after_k8s_min="",
        )
    k8s_before_soperator = k8s_hops[: staging_index + 1]
    k8s_after_soperator = k8s_hops[staging_index:]
    staging_k8s = k8s_hops[staging_index]
    steps: list[str] = []
    if len(k8s_before_soperator) > 1:
        steps.append(f"Kubernetes {' -> '.join(k8s_before_soperator)}")
    steps.append(f"Soperator {' -> '.join(soperator_hops)} while Kubernetes stays {staging_k8s}")
    if len(k8s_after_soperator) > 1:
        steps.append(f"Kubernetes {' -> '.join(k8s_after_soperator)}")
    if not steps:
        return ()
    return ("  - Recommended order: " + "; ".join(steps) + ".",)


def _locked_upgrade_path_stable_json(value: Any) -> str:
    return json.dumps(to_plain_data(value), sort_keys=True, separators=(",", ":"), default=str)


def _locked_upgrade_path_fingerprint(upgrade_path: Mapping[str, Any]) -> str:
    return hashlib.sha256(
        _locked_upgrade_path_stable_json(upgrade_path).encode("utf-8")
    ).hexdigest()


def _locked_upgrade_path_segment_slug(value: str) -> str:
    return re.sub(r"[^a-z0-9]+", "-", str(value or "").lower()).strip("-") or "segment"


def _locked_upgrade_path_action_ids(
    action_ids: Sequence[str],
    *,
    include_one_time_actions: bool,
    include_node_template: bool,
) -> tuple[str, ...]:
    base_actions = tuple(
        dict.fromkeys(
            str(action or "").strip() for action in action_ids if str(action or "").strip()
        )
    )
    one_time_exclusions = {
        ONBOARDING_ACTION_APPROVE_EXTERNAL_UPGRADE,
        ONBOARDING_ACTION_UPGRADE_EXTERNAL_NODE_TEMPLATE,
    }
    if include_one_time_actions:
        selected = list(base_actions)
        if not include_node_template:
            selected = [
                action
                for action in selected
                if action != ONBOARDING_ACTION_UPGRADE_EXTERNAL_NODE_TEMPLATE
            ]
    else:
        selected = []
        if ONBOARDING_ACTION_APPROVE_EXTERNAL_UPGRADE in base_actions:
            selected.append(ONBOARDING_ACTION_APPROVE_EXTERNAL_UPGRADE)
        if include_node_template:
            selected.append(ONBOARDING_ACTION_UPGRADE_EXTERNAL_NODE_TEMPLATE)
    if not include_one_time_actions and not selected and include_node_template:
        selected = [
            ONBOARDING_ACTION_APPROVE_EXTERNAL_UPGRADE,
            ONBOARDING_ACTION_UPGRADE_EXTERNAL_NODE_TEMPLATE,
        ]
    if include_one_time_actions:
        has_one_time = any(action not in one_time_exclusions for action in selected)
        if not has_one_time and not include_node_template:
            return ()
    return tuple(dict.fromkeys(action for action in selected if action))


def _locked_upgrade_path_segment(
    *,
    index: int,
    current_k8s_version: str,
    target_k8s_version: str,
    source_soperator_version: str,
    target_soperator_version: str,
    action_ids: Sequence[str],
    include_soperator_change: bool,
    include_k8s_change: bool,
) -> dict[str, Any]:
    title_parts: list[str] = []
    if include_k8s_change and current_k8s_version and target_k8s_version:
        title_parts.append(f"Kubernetes {current_k8s_version} -> {target_k8s_version}")
    if include_soperator_change and source_soperator_version and target_soperator_version:
        title_parts.append(f"Soperator {source_soperator_version} -> {target_soperator_version}")
    if not title_parts:
        title_parts.append("Soperator external upgrade work")
    kind = "external-upgrade"
    if include_k8s_change and not include_soperator_change:
        kind = "external-node-template-hop"
    elif include_soperator_change and not include_k8s_change:
        kind = "soperator-upgrade"
    descriptor = "-".join(title_parts)
    return {
        "id": f"segment-{index}-{_locked_upgrade_path_segment_slug(descriptor)}",
        "index": index,
        "kind": kind,
        "title": " plus ".join(title_parts),
        "current_k8s_version": current_k8s_version,
        "target_k8s_version": target_k8s_version,
        "source_soperator_version": source_soperator_version,
        "target_soperator_version": target_soperator_version,
        "k8s_upgrade_required": bool(include_k8s_change),
        "soperator_upgrade_required": bool(include_soperator_change),
        "actions": list(action_ids),
    }


def _locked_upgrade_path_from_report(
    *,
    report: Mapping[str, Any] | Any,
    onboarding: Mapping[str, Any],
) -> dict[str, Any]:
    action_ids = tuple(
        str(action or "").strip()
        for action in onboarding.get("actions", []) or []
        if str(action or "").strip()
    )
    if not (set(action_ids) & _SOPERATOR_MIGRATION_ACTIONS):
        return {}
    source_soperator, target_soperator, current_k8s, target_k8s = (
        _soperator_discovery_support_path_values(report)
    )
    source_soperator = _non_empty_text(onboarding.get("source_version")) or source_soperator
    target_soperator = _non_empty_text(onboarding.get("target_version")) or target_soperator
    node_template = onboarding.get("node_template_upgrade")
    if isinstance(node_template, Mapping):
        target_k8s = _non_empty_text(node_template.get("target_k8s_version")) or target_k8s
    support_evidence = _soperator_discovery_support_evidence(report)
    support_finding = next(iter(soperator_upgrade_support_findings(report)), {})
    support_rule_id = _non_empty_text(support_evidence.get("rule_id"))
    support_status = _non_empty_text(support_finding.get("status"))
    recommended_order = _soperator_discovery_support_recommended_order(report)
    soperator_after_k8s_min = _non_empty_text(recommended_order.get("soperator_after_k8s_min"))
    k8s_hops = _soperator_discovery_k8s_hops(current_k8s, target_k8s)
    k8s_pairs = tuple(zip(k8s_hops, k8s_hops[1:], strict=False))
    soperator_change_required = ONBOARDING_ACTION_UPGRADE_SOPERATOR in set(action_ids)
    one_time_actions = set(action_ids) - {
        ONBOARDING_ACTION_APPROVE_EXTERNAL_UPGRADE,
        ONBOARDING_ACTION_UPGRADE_EXTERNAL_NODE_TEMPLATE,
    }
    one_time_required = bool(one_time_actions)
    one_time_hop_index = 0
    if one_time_required and k8s_hops:
        if soperator_change_required and soperator_after_k8s_min:
            staging_index = next(
                (
                    index
                    for index, hop in enumerate(k8s_hops)
                    if _soperator_discovery_k8s_at_least(hop, soperator_after_k8s_min)
                ),
                0,
            )
            one_time_hop_index = max(0, min(staging_index, len(k8s_hops) - 1))
        elif len(k8s_hops) > 1:
            one_time_hop_index = 1
    segments: list[dict[str, Any]] = []
    segment_index = 1

    def _append_segment(
        *,
        current_k8s_version: str,
        target_k8s_version: str,
        source_version: str,
        target_version: str,
        include_one_time_actions: bool,
        include_node_template: bool,
        include_soperator_change: bool,
        include_k8s_change: bool,
    ) -> None:
        nonlocal segment_index
        segment_actions = _locked_upgrade_path_action_ids(
            action_ids,
            include_one_time_actions=include_one_time_actions,
            include_node_template=include_node_template,
        )
        if not segment_actions:
            return
        segments.append(
            _locked_upgrade_path_segment(
                index=segment_index,
                current_k8s_version=current_k8s_version,
                target_k8s_version=target_k8s_version,
                source_soperator_version=source_version,
                target_soperator_version=target_version,
                action_ids=segment_actions,
                include_soperator_change=include_soperator_change,
                include_k8s_change=include_k8s_change,
            )
        )
        segment_index += 1

    if k8s_pairs:
        if one_time_required and one_time_hop_index == 0:
            staging_k8s = k8s_hops[0]
            _append_segment(
                current_k8s_version=staging_k8s,
                target_k8s_version=staging_k8s,
                source_version=source_soperator,
                target_version=target_soperator,
                include_one_time_actions=True,
                include_node_template=False,
                include_soperator_change=soperator_change_required,
                include_k8s_change=False,
            )
        for pair_index, (hop_current, hop_target) in enumerate(k8s_pairs):
            is_one_time_hop = (
                one_time_required
                and one_time_hop_index > 0
                and pair_index == one_time_hop_index - 1
            )
            before_one_time = (
                one_time_required and one_time_hop_index > 0 and pair_index < one_time_hop_index - 1
            )
            if before_one_time:
                source_version = source_soperator
                target_version = source_soperator
            elif is_one_time_hop:
                source_version = source_soperator
                target_version = target_soperator
            else:
                source_version = target_soperator
                target_version = target_soperator
            _append_segment(
                current_k8s_version=hop_current,
                target_k8s_version=hop_target,
                source_version=source_version,
                target_version=target_version,
                include_one_time_actions=is_one_time_hop,
                include_node_template=True,
                include_soperator_change=is_one_time_hop and soperator_change_required,
                include_k8s_change=hop_current != hop_target,
            )
        if one_time_required and one_time_hop_index > len(k8s_pairs):
            _append_segment(
                current_k8s_version=k8s_hops[-1],
                target_k8s_version=k8s_hops[-1],
                source_version=source_soperator,
                target_version=target_soperator,
                include_one_time_actions=True,
                include_node_template=False,
                include_soperator_change=soperator_change_required,
                include_k8s_change=False,
            )
    elif one_time_required or action_ids:
        current_version = current_k8s or target_k8s
        include_node_template = ONBOARDING_ACTION_UPGRADE_EXTERNAL_NODE_TEMPLATE in set(action_ids)
        _append_segment(
            current_k8s_version=current_version,
            target_k8s_version=target_k8s or current_version,
            source_version=source_soperator,
            target_version=target_soperator,
            include_one_time_actions=one_time_required,
            include_node_template=include_node_template,
            include_soperator_change=soperator_change_required,
            include_k8s_change=bool(include_node_template and current_version != target_k8s),
        )
    if not segments:
        return {}
    recommended_steps = tuple(
        line.removeprefix("  - Recommended order: ").removesuffix(".")
        for line in _soperator_discovery_upgrade_order_steps(
            k8s_hops=k8s_hops,
            soperator_hops=_soperator_discovery_soperator_hops(
                source_soperator=source_soperator,
                target_soperator=target_soperator,
            ),
            soperator_after_k8s_min=soperator_after_k8s_min,
        )
    )
    return {
        "schema": _SOPERATOR_LOCKED_UPGRADE_PATH_SCHEMA,
        "locked": True,
        "source_k8s_version": current_k8s,
        "target_k8s_version": target_k8s,
        "source_soperator_version": source_soperator,
        "target_soperator_version": target_soperator,
        "support_status": support_status,
        "support_rule_id": support_rule_id,
        "recommended_order": list(recommended_steps),
        "recommended_order_policy": copy.deepcopy(to_plain_data(recommended_order)),
        "segments": segments,
    }


def _soperator_discovery_upgrade_path_lines(
    report: Mapping[str, Any] | Any,
) -> tuple[str, ...]:
    source_soperator, target_soperator, current_k8s, target_k8s = (
        _soperator_discovery_support_path_values(report)
    )
    k8s_hops = _soperator_discovery_k8s_hops(current_k8s, target_k8s)
    recommended_order = _soperator_discovery_support_recommended_order(report)
    soperator_after_k8s_min = _non_empty_text(recommended_order.get("soperator_after_k8s_min"))
    soperator_hops = _soperator_discovery_soperator_hops(
        source_soperator=source_soperator,
        target_soperator=target_soperator,
    )
    if not k8s_hops and not soperator_hops:
        return ()
    lines = ["- Upgrade path evaluation:"]
    if k8s_hops:
        lines.append(f"  - Kubernetes: {' -> '.join(k8s_hops)}")
    if soperator_hops:
        lines.append(f"  - Soperator: {' -> '.join(soperator_hops)}")
    lines.extend(
        _soperator_discovery_upgrade_order_steps(
            k8s_hops=k8s_hops,
            soperator_hops=soperator_hops,
            soperator_after_k8s_min=soperator_after_k8s_min,
        )
    )
    return tuple(lines)


def _soperator_discovery_upgrade_guidance_lines(
    report: Mapping[str, Any] | Any,
) -> tuple[str, ...]:
    lines = list(_soperator_discovery_upgrade_path_lines(report))
    lines.extend(
        _soperator_support_policy_plan_lines(
            report,
            reject_disposition="execute requires override",
            label="Soperator upgrade path",
            rejection_subject="Soperator upgrade-path rejection",
        )
    )
    if lines:
        lines.append(
            "- Discovery is read-only; unsupported or not-validated paths are gated "
            "when accepting onboarding or executing upgrade."
        )
    return tuple(lines)


def _apply_soperator_support_policy_to_target_row(
    target_row: dict[str, Any],
    *,
    allow_unsupported_soperator_upgrade_path: bool,
    command_name: str,
) -> None:
    report_material = target_row.get(_SOPERATOR_DISCOVERY_REPORT_PRIVATE_KEY)
    if not isinstance(report_material, dict):
        return
    report = report_material.get("report")
    if not isinstance(report, Mapping):
        return
    _enforce_soperator_support_policy_for_report(
        report,
        allow_unsupported_soperator_upgrade_path=allow_unsupported_soperator_upgrade_path,
        command_name=command_name,
    )
    override_required = soperator_upgrade_support_requires_override(report)
    if allow_unsupported_soperator_upgrade_path and override_required:
        report = _soperator_support_override_report_mapping(report)
        report_material["report"] = report
    support_findings = soperator_upgrade_support_findings(report)
    if not support_findings:
        return
    onboarding = target_row.get("soperator_onboarding")
    if not isinstance(onboarding, dict):
        return
    selected = support_findings[0]
    evidence = _soperator_support_finding_evidence(selected)
    onboarding["support_status"] = _non_empty_text(selected.get("status"))
    onboarding["support_rule_id"] = _non_empty_text(evidence.get("rule_id"))
    onboarding["support_message"] = _non_empty_text(selected.get("message"))
    onboarding["support_override_used"] = bool(evidence.get("override_used") is True)


def _soperator_source_version_sort_key(version: str) -> tuple[int, ...]:
    match = re.search(r"([0-9]+(?:\.[0-9]+){0,3})", str(version or ""))
    if match is None:
        return ()
    return tuple(int(part) for part in match.group(1).split("."))


def _soperator_source_version_choices() -> list[OptionChoice]:
    versions = sorted(
        set(soperator_migration_profile_versions()),
        key=_soperator_source_version_sort_key,
        reverse=True,
    )
    choices: list[OptionChoice] = []
    for version in versions:
        profile = soperator_migration_profile_for_version(version)
        profile_id = _non_empty_text(profile.get("profile_id")) if profile else ""
        label = f"{version}  ({profile_id})" if profile_id else version
        choices.append(OptionChoice(value=version, label=label))
    return choices


def _validate_soperator_source_version(value: object) -> str:
    normalized = normalize_soperator_release_version(str(value or ""))
    if not normalized:
        raise ValueError("Enter a Soperator release version such as 3.0.5.")
    if (
        soperator_migration_profile_for_version(
            normalized,
            allow_generation_fallback=True,
        )
        is None
    ):
        choices = [choice.value for choice in _soperator_source_version_choices()]
        preview = ", ".join(choices[:8])
        suffix = f" Known profile versions include: {preview}." if preview else ""
        raise ValueError(
            f"Soperator source version '{value}' does not match an exact committed "
            "upgrade compatibility profile row or known major-generation profile."
            f"{suffix}"
        )
    return normalized


def _soperator_onboarding_report_needs_source_version(report: Any) -> bool:
    for finding in getattr(report, "findings", ()) or ():
        if str(getattr(finding, "status", "") or "").strip() == "source-version-required":
            return True
    return False


def _prompt_manual_soperator_source_version() -> str:
    field = "deploy.targets[].soperator_onboarding.source_version"
    while True:
        raw, should_stop = _prompt_scalar_override(
            field,
            "",
            type_hint="string",
            required=True,
        )
        if should_stop:
            raise _WizardQuitRequested
        if _wizard_backtrack_requested(raw):
            return ""
        try:
            return _validate_soperator_source_version(raw)
        except ValueError as exc:
            console.print(f"{error_markup('Invalid value')}. {exc}")


def _prompt_soperator_onboarding_source_version(report: Any) -> str:
    if not _soperator_onboarding_report_needs_source_version(report):
        return ""
    source_version = _non_empty_text(getattr(report, "source_version", ""))
    if source_version:
        console.print(
            f"[dim]Detected Soperator version {source_version}, but cxcli also found "
            "a Soperator Helm release with non-standard identity. Confirm the "
            "source Soperator version so cxcli can match an exact committed "
            "upgrade compatibility profile row or known major-generation profile "
            "before managing the release.[/dim]"
        )
    else:
        console.print(
            "[dim]Soperator CRDs were detected, but cxcli could not detect a compatible "
            "Helm release version. Select the source Soperator version so cxcli can match "
            "an exact committed upgrade compatibility profile row or known major-generation "
            "profile.[/dim]"
        )
    field = "deploy.targets[].soperator_onboarding.source_version"
    with _soperator_onboarding_status(
        "Loading Soperator upgrade compatibility profile versions..."
    ):
        choices = _soperator_source_version_choices()
    choices.append(
        OptionChoice(
            value=_SOPERATOR_SOURCE_VERSION_MANUAL_CHOICE,
            label="Enter another source version manually",
        )
    )
    rendered_label = _prompt_label_with_type(field, type_hint="string", required=True)

    if _is_tty_session():
        try:
            import questionary

            selected = _ask_questionary_with_wizard_navigation(
                questionary.select(
                    rendered_label,
                    choices=[
                        questionary.Choice(title=choice.label, value=choice.value)
                        for choice in choices
                    ],
                    instruction="Use arrows; q=back; qq=quit; Enter=select.",
                    qmark="",
                )
            )
            if selected is None or selected == _WIZARD_QUIT_CHOICE:
                raise _WizardQuitRequested
            if selected == _WIZARD_BACK_CHOICE:
                return ""
            if selected == _SOPERATOR_SOURCE_VERSION_MANUAL_CHOICE:
                return _prompt_manual_soperator_source_version()
            return _validate_soperator_source_version(selected)
        except _WizardQuitRequested:
            raise
        except (KeyboardInterrupt, EOFError, typer.Abort):
            raise _WizardQuitRequested from None
        except ValueError as exc:
            console.print(f"{error_markup('Invalid value')}. {exc}")
        except Exception:
            pass

    console.print(f"[cyan]{field} options:[/cyan]")
    for index, choice in enumerate(choices, start=1):
        console.print(f"    [{index}] {choice.label}")
    prompt_suffix = _wizard_field_prompt_suffix(rendered_label)
    option_values = {str(choice.value).strip(): str(choice.value).strip() for choice in choices}
    while True:
        try:
            raw = typer.prompt(
                f"{prompt_suffix} (index, version, or manual)",
                default="",
            ).strip()
        except (KeyboardInterrupt, EOFError, typer.Abort):
            raise _WizardQuitRequested from None
        if raw == WIZARD_ABORT_TOKEN:
            raise _WizardQuitRequested
        if raw == WIZARD_EXIT_TOKEN:
            return ""
        if not raw:
            console.print(f"{error_markup('Invalid value')}. This field is required.")
            continue
        selected = raw
        if raw.isdigit():
            index = int(raw)
            if 1 <= index <= len(choices):
                selected = str(choices[index - 1].value)
            else:
                console.print(
                    f"{error_markup('Invalid option index')}. "
                    f"Use a value between 1 and {len(choices)}."
                )
                continue
        elif raw.lower() in {"manual", "m"}:
            selected = _SOPERATOR_SOURCE_VERSION_MANUAL_CHOICE
        elif raw in option_values:
            selected = option_values[raw]
        if selected == _SOPERATOR_SOURCE_VERSION_MANUAL_CHOICE:
            return _prompt_manual_soperator_source_version()
        try:
            return _validate_soperator_source_version(selected)
        except ValueError as exc:
            console.print(f"{error_markup('Invalid value')}. {exc}")


def _soperator_onboarding_report_with_source_version(
    report: Any,
    *,
    snapshot: Mapping[str, Any],
    target_ref: str,
    pinned_chart_version: str,
    pinned_app_version: str,
    approved_target_chart_version: str = "",
    target_k8s_version: str | None = None,
    source_version: str | None,
    interactive: bool,
) -> Any:
    source_version_override = ""
    if source_version:
        source_version_override = _validate_soperator_source_version(source_version)
    elif interactive:
        source_version_override = _prompt_soperator_onboarding_source_version(report)
    if not source_version_override:
        return report
    return analyze_soperator_onboarding_snapshot(
        snapshot,
        target_ref=target_ref,
        pinned_chart_version=pinned_chart_version,
        pinned_app_version=pinned_app_version,
        approved_target_chart_version=approved_target_chart_version,
        source_version_override=source_version_override,
        target_k8s_version=target_k8s_version,
    )


def _print_soperator_onboarding_report_summary(report: Any) -> None:
    labels = {
        "no-soperator-detected": "No Soperator detected",
        "existing-soperator-supported": "Existing Soperator supported for migration",
        "existing-soperator-target": "Existing Soperator matches target",
        "existing-soperator-unknown": "Existing Soperator requires an explicit action",
        "existing-soperator-newer": "Existing Soperator is newer than cxcli target",
        "analysis-incomplete": "Analysis incomplete",
    }
    console.print(
        f"[dim]Soperator onboarding state: {labels.get(report.state, report.state)}[/dim]"
    )
    source_version = _non_empty_text(getattr(report, "source_version", ""))
    target_version = _non_empty_text(getattr(report, "target_version", ""))
    migration_profile_id = _non_empty_text(getattr(report, "migration_profile_id", ""))
    if target_version:
        console.print(f"[dim]Target Soperator version: {target_version}[/dim]")
    if source_version:
        console.print(f"[dim]Detected Soperator version: {source_version}[/dim]")
    current_k8s_version, target_k8s_version = soperator_discovery_report_k8s_versions(report)
    if current_k8s_version:
        console.print(f"[dim]Detected Kubernetes version: {current_k8s_version}[/dim]")
    if target_k8s_version:
        console.print(f"[dim]Target Kubernetes version: {target_k8s_version}[/dim]")
    if migration_profile_id:
        console.print(f"[dim]Upgrade profile: {migration_profile_id}[/dim]")
    for finding in report.findings:
        print_info_finding = (finding.layer == "gpu-stack" and finding.status == "verified") or (
            finding.layer in {"placements", "storage-sfs", "mk8s-node-template"}
            and finding.status == "target-compatible"
        )
        if finding.severity in {"required", "recommended"} or print_info_finding:
            console.print(f"[dim]- {finding.layer}: {finding.status} - {finding.message}[/dim]")
    console.print(
        "[dim]Onboard discovery is read-only for the live cluster; this command records "
        "config decisions only and does not mutate external resources.[/dim]"
    )


def _soperator_onboarding_report_mapping_from_target_row(
    target_row: Mapping[str, Any],
) -> Mapping[str, Any]:
    report_material = target_row.get(_SOPERATOR_DISCOVERY_REPORT_PRIVATE_KEY)
    if not isinstance(report_material, Mapping):
        return {}
    report = report_material.get("report")
    return report if isinstance(report, Mapping) else {}


def _soperator_onboarding_find_report_finding(
    report: Mapping[str, Any],
    *,
    layer: str,
    status: str,
) -> Mapping[str, Any]:
    findings = report.get("findings")
    if not isinstance(findings, Sequence) or isinstance(findings, (str, bytes, bytearray)):
        return {}
    for finding in findings:
        if not isinstance(finding, Mapping):
            continue
        if (
            str(finding.get("layer", "") or "").strip() == layer
            and str(finding.get("status", "") or "").strip() == status
        ):
            return finding
    return {}


def _soperator_onboarding_layout_groups_text(groups_by_role: Mapping[str, Sequence[str]]) -> str:
    role_order = (*ONBOARDING_SERVICE_ROLES, "worker", "worker-cpu", "worker-gpu")
    parts: list[str] = []
    for role in role_order:
        raw_groups = groups_by_role.get(role)
        if not isinstance(raw_groups, Sequence) or isinstance(
            raw_groups,
            (str, bytes, bytearray),
        ):
            continue
        groups = [_non_empty_text(group) for group in raw_groups if _non_empty_text(group)]
        if groups:
            parts.append(f"{role}: {', '.join(groups)}")
    extra_roles = sorted(
        role for role in groups_by_role if role not in set(role_order) and _non_empty_text(role)
    )
    for role in extra_roles:
        raw_groups = groups_by_role.get(role)
        if not isinstance(raw_groups, Sequence) or isinstance(
            raw_groups,
            (str, bytes, bytearray),
        ):
            continue
        groups = [_non_empty_text(group) for group in raw_groups if _non_empty_text(group)]
        if groups:
            parts.append(f"{role}: {', '.join(groups)}")
    return "; ".join(parts)


def _print_soperator_onboarding_decision_summary(target_row: Mapping[str, Any]) -> None:
    onboarding = target_row.get("soperator_onboarding")
    if not isinstance(onboarding, Mapping):
        return
    report = _soperator_onboarding_report_mapping_from_target_row(target_row)
    storage_mode = _non_empty_text(onboarding.get("storage_mode"))
    compute_mode = _non_empty_text(onboarding.get("compute_mode"))
    storage_compatible = bool(
        _soperator_onboarding_find_report_finding(
            report,
            layer="storage-sfs",
            status="target-compatible",
        )
    )
    compute_finding = _soperator_onboarding_find_report_finding(
        report,
        layer="placements",
        status="target-compatible",
    )
    compute_compatible = bool(compute_finding)

    console.print("[dim]Soperator onboarding decisions:[/dim]")
    if storage_mode == ONBOARDING_STORAGE_MODE_KEEP_EXISTING:
        if storage_compatible:
            console.print(
                "[dim]- Storage layout decision: keep existing storage. Existing "
                f"{', '.join(ONBOARDING_REQUIRED_STORAGE_KEYS)} storage matches the target "
                "Soperator layout; no aligned SFS creation or storage data migration is "
                "planned.[/dim]"
            )
        else:
            console.print(
                "[dim]- Storage layout decision: keep existing storage. cxcli will preserve "
                "the discovered storage contract and will not plan aligned SFS creation; "
                "review storage-sfs findings in the discovery bundle before upgrade.[/dim]"
            )
    elif storage_mode == ONBOARDING_STORAGE_MODE_CREATE_ALIGNED_SFS:
        console.print(
            "[dim]- Storage layout decision: create aligned SFS. cxcli records aligned "
            "SFS remediation for the external upgrade plan; storage changes require "
            "customer approval before execution.[/dim]"
        )

    if compute_mode == ONBOARDING_COMPUTE_MODE_KEEP_EXISTING:
        if compute_compatible:
            roles = compute_finding.get("evidence")
            role_text = ""
            if isinstance(roles, Mapping):
                raw_roles = roles.get("roles")
                if isinstance(raw_roles, Mapping):
                    role_text = _soperator_onboarding_layout_groups_text(raw_roles)
            suffix = f" Discovered placements: {role_text}." if role_text else ""
            console.print(
                "[dim]- Compute layout decision: keep existing compute. Existing "
                "Soperator service-role and worker node-group labels match the target "
                "layout; no replacement compute node groups or compute migration are "
                f"planned.{suffix}[/dim]"
            )
        else:
            console.print(
                "[dim]- Compute layout decision: keep existing compute. cxcli will reuse "
                "discovered node groups through apps.charts[].placements; no replacement "
                "compute node groups are planned.[/dim]"
            )
    elif compute_mode == ONBOARDING_COMPUTE_MODE_CREATE_ALIGNED_NODE_GROUPS:
        console.print(
            "[dim]- Compute layout decision: create profile-aligned node groups. cxcli "
            "records compute remediation for the external upgrade plan; worker migration "
            "is guarded by ext-soperator upgrade.[/dim]"
        )
    for line in _soperator_support_policy_plan_lines(
        report,
        reject_disposition="accepted plan requires override",
    ):
        console.print(f"[dim]{line}[/dim]", soft_wrap=True)


